routines.definition:
create or replace function public._import_review_assert_actor_v1(p_actor_user_id uuid)
returns void
language plpgsql
security definer
set search_path to 'public', 'pg_temp'
as $function$
begin
  if p_actor_user_id is null or not exists (
    select 1 from public.tms_users u where u.id=p_actor_user_id and coalesce(u.is_active,false)
  ) then
    raise exception 'IMPORT_REVIEW_ACTOR_INVALID' using errcode='42501';
  end if;
end
$function$;

routines.body:
begin
  if p_actor_user_id is null or not exists (
    select 1 from public.tms_users u where u.id=p_actor_user_id and coalesce(u.is_active,false)
  ) then
    raise exception 'IMPORT_REVIEW_ACTOR_INVALID' using errcode='42501';
  end if;
end

declare
  v_source text:=upper(btrim(coalesce(p_source_system::text,'')));
  v_result uuid[]:=array[]::uuid[];
begin
  if coalesce(cardinality(p_timesheet_ids),0)>100 then
    raise exception 'IMPORT_REVIEW_AUTO_AUTHORISE_SCOPE_TOO_LARGE' using errcode='54000';
  end if;
  if v_source not in ('NHSP','HEALTHROSTER','HEALTHROSTER_DAILY') then
    raise exception 'IMPORT_REVIEW_AUTO_AUTHORISE_SOURCE_INVALID' using errcode='22023';
  end if;

  select coalesce(array_agg(target.timesheet_id order by target.timesheet_id),array[]::uuid[])
  into v_result
  from (
    select distinct t.timesheet_id
    from unnest(coalesce(p_timesheet_ids,array[]::uuid[])) requested(timesheet_id)
    join public.timesheets t
      on t.timesheet_id=requested.timesheet_id
     and t.is_current=true
     and t.revoked_at is null
    join public.contracts c on c.id=t.contract_id
    cross join lateral (
      select public._import_review_timesheet_protection_core_v1(t.timesheet_id) as value
    ) protection
    cross join lateral (
      select public.import_auto_authorise_policy_resolve_v2(
        p_source_system,c.client_id,c.id,t.timesheet_id,t.week_ending_date,
        coalesce(p_validation_context,false)
      ) as value
    ) policy
    where t.authorised_at_server is null
      -- Import correction reversals/replacements are mandatory-authorisation
      -- targets owned by the transactional route, not policy-controlled new
      -- timesheets.  Keep the configuration helper strictly ordinary-only.
      and not (coalesce(t.is_adjustment,false) and t.correction_id is not null)
      and not exists (
        select 1 from public.timesheets_financials tf
        where tf.timesheet_id=t.timesheet_id and tf.is_current=true
          and tf.authorised_at_utc is not null
      )
      and not exists (
        select 1 from public.contract_weeks cw
        where cw.timesheet_id=t.timesheet_id and upper(coalesce(cw.status::text,''))='AUTHORISED'
      )
      and coalesce((protection.value->>'paid')::boolean,false)=false
      and coalesce((protection.value->>'invoice_locked')::boolean,false)=false
      and coalesce((protection.value->>'active_pay_draft')::boolean,false)=false
      and public._import_review_timesheet_has_calculated_expenses_core_v1(t.timesheet_id)=false
      and coalesce((policy.value->>'effective_value')::boolean,false)=true
  ) target;
  return v_result;
end

routines.definition:
create or replace function public._import_review_effective_authority_core_v1(
  p_source_route text,
  p_contract_id uuid,
  p_client_id uuid,
  p_evidence_date date default null
)
returns table (
  route_eligible boolean,
  validation_eligible boolean,
  import_authoritative boolean,
  authority_mode text,
  authority_basis text,
  effective_is_nhsp boolean,
  effective_autoprocess_hr boolean,
  effective_requires_hr boolean,
  effective_no_timesheet_required boolean,
  settings_as_of_date date,
  client_settings_id uuid,
  client_settings_effective_from date,
  client_settings_updated_at timestamptz,
  contract_updated_at timestamptz,
  authority_fingerprint text
)
language plpgsql
stable
security definer
set search_path = pg_catalog, public, private, extensions, pg_temp
as $function$
declare
  v_route text:=upper(btrim(coalesce(p_source_route,'')));
  v_workflow text;
  v_authority jsonb;
  v_is_nhsp boolean;
  v_requires_hr boolean;
  v_autoprocess_hr boolean;
  v_no_timesheet boolean;
  v_route_ok boolean;
  v_validation boolean;
  v_authoritative boolean;
begin
  if p_evidence_date is null then
    raise exception 'IMPORT_AUTHORITY_EVIDENCE_DATE_REQUIRED' using errcode='22023';
  end if;
  v_workflow:=case when v_route in ('HR_DAILY','HEALTHROSTER_DAILY') then 'DAILY' else 'IMPORT' end;
  v_authority:=private._contract_settings_effective_core_v1(
    p_client_id,p_contract_id,p_evidence_date,v_workflow,null
  );
  v_is_nhsp:=coalesce((v_authority#>>'{values,is_nhsp}')::boolean,false);
  v_requires_hr:=coalesce((v_authority#>>'{values,requires_hr}')::boolean,false);
  v_autoprocess_hr:=coalesce((v_authority#>>'{values,autoprocess_hr}')::boolean,false);
  v_no_timesheet:=coalesce((v_authority#>>'{values,no_timesheet_required}')::boolean,false);
  v_route_ok:=case
    when v_route='NHSP' then v_is_nhsp
    when v_route in ('HR_WEEKLY','HEALTHROSTER','HEALTHROSTER_WEEKLY','HR_DAILY','HEALTHROSTER_DAILY')
      then v_autoprocess_hr and (v_requires_hr or v_no_timesheet)
    else false end;
  v_validation:=case
    when v_route in ('HR_WEEKLY','HEALTHROSTER','HEALTHROSTER_WEEKLY','HR_DAILY','HEALTHROSTER_DAILY')
      then v_requires_hr and v_autoprocess_hr and not v_no_timesheet
    else false end;
  v_authoritative:=case
    when v_route='NHSP' then v_is_nhsp
    when v_route in ('HR_WEEKLY','HEALTHROSTER','HEALTHROSTER_WEEKLY','HR_DAILY','HEALTHROSTER_DAILY')
      then v_autoprocess_hr and v_no_timesheet
    else false end;
  return query select
    v_route_ok,v_validation,v_authoritative,
    case when not v_route_ok then 'OUT_OF_SCOPE'
      when v_authoritative then 'AUTHORITATIVE'
      when v_validation then 'VALIDATION_ONLY' else 'OUT_OF_SCOPE' end,
    case when coalesce((v_authority->>'override_client_settings')::boolean,false)
      then 'CONTRACT_OVERRIDE' else 'CLIENT_SETTINGS' end,
    v_is_nhsp,v_autoprocess_hr,v_requires_hr,v_no_timesheet,
    p_evidence_date,
    nullif(v_authority->>'client_settings_id','')::uuid,
    nullif(v_authority->>'client_settings_effective_from','')::date,
    nullif(v_authority->>'client_settings_updated_at','')::timestamptz,
    nullif(v_authority->>'contract_updated_at','')::timestamptz,
    v_authority->>'authority_fingerprint';
end
$function$;

routines.body:
declare
  v_route text:=upper(btrim(coalesce(p_source_route,'')));
  v_workflow text;
  v_authority jsonb;
  v_is_nhsp boolean;
  v_requires_hr boolean;
  v_autoprocess_hr boolean;
  v_no_timesheet boolean;
  v_route_ok boolean;
  v_validation boolean;
  v_authoritative boolean;
begin
  if p_evidence_date is null then
    raise exception 'IMPORT_AUTHORITY_EVIDENCE_DATE_REQUIRED' using errcode='22023';
  end if;
  v_workflow:=case when v_route in ('HR_DAILY','HEALTHROSTER_DAILY') then 'DAILY' else 'IMPORT' end;
  v_authority:=private._contract_settings_effective_core_v1(
    p_client_id,p_contract_id,p_evidence_date,v_workflow,null
  );
  v_is_nhsp:=coalesce((v_authority#>>'{values,is_nhsp}')::boolean,false);
  v_requires_hr:=coalesce((v_authority#>>'{values,requires_hr}')::boolean,false);
  v_autoprocess_hr:=coalesce((v_authority#>>'{values,autoprocess_hr}')::boolean,false);
  v_no_timesheet:=coalesce((v_authority#>>'{values,no_timesheet_required}')::boolean,false);
  v_route_ok:=case
    when v_route='NHSP' then v_is_nhsp
    when v_route in ('HR_WEEKLY','HEALTHROSTER','HEALTHROSTER_WEEKLY','HR_DAILY','HEALTHROSTER_DAILY')
      then v_autoprocess_hr and (v_requires_hr or v_no_timesheet)
    else false end;
  v_validation:=case
    when v_route in ('HR_WEEKLY','HEALTHROSTER','HEALTHROSTER_WEEKLY','HR_DAILY','HEALTHROSTER_DAILY')
      then v_requires_hr and v_autoprocess_hr and not v_no_timesheet
    else false end;
  v_authoritative:=case
    when v_route='NHSP' then v_is_nhsp
    when v_route in ('HR_WEEKLY','HEALTHROSTER','HEALTHROSTER_WEEKLY','HR_DAILY','HEALTHROSTER_DAILY')
      then v_autoprocess_hr and v_no_timesheet
    else false end;
  return query select
    v_route_ok,v_validation,v_authoritative,
    case when not v_route_ok then 'OUT_OF_SCOPE'
      when v_authoritative then 'AUTHORITATIVE'
      when v_validation then 'VALIDATION_ONLY' else 'OUT_OF_SCOPE' end,
    case when coalesce((v_authority->>'override_client_settings')::boolean,false)
      then 'CONTRACT_OVERRIDE' else 'CLIENT_SETTINGS' end,
    v_is_nhsp,v_autoprocess_hr,v_requires_hr,v_no_timesheet,
    p_evidence_date,
    nullif(v_authority->>'client_settings_id','')::uuid,
    nullif(v_authority->>'client_settings_effective_from','')::date,
    nullif(v_authority->>'client_settings_updated_at','')::timestamptz,
    nullif(v_authority->>'contract_updated_at','')::timestamptz,
    v_authority->>'authority_fingerprint';
end

routines.definition:
create or replace function public._import_review_effective_invoice_balance_core_v1(
  p_import_id uuid,
  p_source_items jsonb,
  p_max_sources integer default 100,
  p_max_invoice_lines_per_source integer default 512,
  p_max_audit_rows_per_source integer default 256,
  p_max_operations_per_source integer default 128
)
returns table(source_identity text,balance_json jsonb)
language plpgsql
security invoker
set search_path to 'public','extensions','pg_temp'
as $function$
declare
  v_item jsonb;
  v_source_identity text;
  v_source_system text;
  v_external_row_key text;
  v_invoice_stream text;
  v_source_shift_id uuid;
  v_source_timesheet_id uuid;
  v_hr_row_id uuid;
  v_candidate_id uuid;
  v_client_id uuid;
  v_contract_id uuid;
