        jsonb_build_object('invoice_id',coalesce(p_invoice_id::text,''),'sqlstate',v_dbg_sqlstate,'error',v_dbg_error,'stats',v_dbg_stats,'steps',v_dbg_steps),
        'timesheets_financials',
