    ELSE COALESCE(NULLIF(BTRIM(COALESCE(v_state->>'reason', '')), ''), CASE WHEN v_blocked THEN 'CANDIDATE_SERIAL_BLOCKED' ELSE 'CANDIDATE_SERIAL_CLEAR' END)
  END;

