                  'policy_snapshot_json', s.policy_snapshot_json,
                  'rate_source_refs_json', s.rate_source_refs_json,
                  'expense', jsonb_build_object(
                    'category', 'ACCOMMODATION',
                    'note', v_note_accom,
                    'pay_ex_vat', pay_ex,
