                paper_ts_r2_key, meta_json, source_key
              )
              values (
                v_invoice_id, s.timesheet_id, s.booking_id, line_desc,
                0,0,0,0,0,
                null,null,null,null,null,
      coalesce(s.charge_day,null),
      coalesce(s.charge_night,null),
