                null,null,null,null,null,
      coalesce(s.charge_day,null),
      coalesce(s.charge_night,null),
      coalesce(s.charge_sat,null),
      coalesce(s.charge_sun,null),
      coalesce(s.charge_bh,null),

                pay_ex, charge_ex, margin_ex,
