                    coalesce(v_cs.requires_hr, false),
                    false
                  ) as req_hr
                into sb_requires_hr
                from cons;
-- Attach flags use precedence: contract → client_settings → settings_defaults → true
                sb_hr_attach := coalesce(v_hr_attach_any, true);

