        attempt_lease_expires_at_utc=null,
        payment_scope_json=coalesce(mail_row.payment_scope_json,'{}'::jsonb)
          ||jsonb_build_object(
            'candidate_manager_mail_retired',true,
            'candidate_manager_mail_retired_at_utc',p_now_utc,
