create or replace function private._candidate_daily_factual_receipt_v1(
  p_workflow_id uuid,
  p_generation integer,
  p_input_sha256_hex text,
  p_electronic_patch jsonb,
  p_now_utc timestamptz default now()
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_workflow public.candidate_submission_workflows%rowtype;
  v_timesheet public.timesheets%rowtype;
  v_context jsonb;
  v_input jsonb;
  v_patch jsonb;
  v_start timestamptz;
  v_end timestamptz;
  v_break_start timestamptz;
  v_break_end timestamptz;
  v_break_minutes integer;
  v_minutes integer;
  v_candidate_signature public.candidate_submission_components%rowtype;
  v_manager_signature public.candidate_submission_components%rowtype;
begin
  select * into v_workflow from public.candidate_submission_workflows
    where id=p_workflow_id and generation=p_generation for update;
  if not found or v_workflow.workflow_kind<>'DAILY' or v_workflow.scope<>'DAILY'
     or v_workflow.route<>'PHONE' or v_workflow.state<>'READY_TO_FINALISE'
     or v_workflow.contract_week_id is not null or v_workflow.manager_approved_at_utc is null then
    raise exception 'CANDIDATE_DAILY_RECEIPT_NOT_READY' using errcode='55000';
  end if;
  v_context:=private._candidate_daily_receipt_context_v1(
    v_workflow.environment,v_workflow.candidate_id,v_workflow.target_timesheet_id,true,p_now_utc);
  if not coalesce((v_context->>'candidate_first_receipt')::boolean,false)
     or not coalesce((v_context->>'office_resolution_pending')::boolean,false) then
    raise exception 'CANDIDATE_DAILY_RECEIPT_CONTEXT_CHANGED' using errcode='40001';
  end if;
  select * into v_timesheet from public.timesheets
    where timesheet_id=v_workflow.target_timesheet_id and is_current for update;
  if v_timesheet.timesheet_id is null or v_timesheet.authorised_at_server is not null then
    raise exception 'CANDIDATE_RECORD_MUTATION_LOCKED' using errcode='55000';
  end if;
  v_input:=private._candidate_daily_canonical_save_input_v1(v_workflow.id,v_workflow.generation);
  if p_input_sha256_hex is null or p_input_sha256_hex!~'^[a-f0-9]{64}$'
     or encode(private._candidate_sha256_jsonb_v1(v_input),'hex')<>p_input_sha256_hex then
    raise exception 'CANDIDATE_IMMUTABLE_SUBMISSION_MISMATCH' using errcode='40001';
  end if;
  v_patch:=v_input->'timesheet_patch_json';
  v_start:=nullif(v_patch->>'worked_start_iso','')::timestamptz;
  v_end:=nullif(v_patch->>'worked_end_iso','')::timestamptz;
  v_break_start:=nullif(v_patch->>'break_start_iso','')::timestamptz;
  v_break_end:=nullif(v_patch->>'break_end_iso','')::timestamptz;
  v_break_minutes:=nullif(v_patch->>'break_minutes','')::integer;
  if v_start is null or v_end is null or not isfinite(v_start) or not isfinite(v_end)
     or v_end<=v_start or (v_start at time zone 'Europe/London')::date<>v_workflow.work_date
     or (v_end at time zone 'Europe/London')::date not between v_workflow.work_date and v_workflow.work_date+1
     or extract(second from v_start)<>0 or extract(second from v_end)<>0
     or (v_break_start is null)<>(v_break_end is null)
     or (v_break_start is not null and (
       not isfinite(v_break_start) or not isfinite(v_break_end)
       or v_break_start<v_start or v_break_end>v_end or v_break_end<=v_break_start
       or extract(second from v_break_start)<>0 or extract(second from v_break_end)<>0)) then
    raise exception 'CANDIDATE_DAILY_HOURS_INVALID' using errcode='22023';
  end if;
  if v_break_start is not null then
    if v_break_minutes is not null and v_break_minutes<>
        (extract(epoch from (v_break_end-v_break_start))/60)::integer then
      raise exception 'CANDIDATE_DAILY_BREAK_INVALID' using errcode='22023';
    end if;
    v_break_minutes:=(extract(epoch from (v_break_end-v_break_start))/60)::integer;
  end if;
  if v_break_minutes is null or v_break_minutes<0
     or v_break_minutes>=extract(epoch from (v_end-v_start))/60
     or jsonb_typeof(v_patch->'actual_schedule_json') is distinct from 'array'
     or jsonb_array_length(v_patch->'actual_schedule_json')<>1
     or exists(select 1 from jsonb_array_elements(v_patch->'actual_schedule_json') d
       where d->>'date' is distinct from v_workflow.work_date::text) then
    raise exception 'CANDIDATE_DAILY_BREAK_INVALID' using errcode='22023';
  end if;
  v_minutes:=(extract(epoch from (v_end-v_start))/60)::integer-v_break_minutes;
  select * into v_candidate_signature from public.candidate_submission_components
    where id=v_workflow.candidate_signature_component_id and workflow_id=v_workflow.id
      and document_role='CANDIDATE_SIGNATURE' and state='IMMUTABLE';
  select * into v_manager_signature from public.candidate_submission_components
    where id=v_workflow.manager_signature_component_id and workflow_id=v_workflow.id
      and document_role='MANAGER_SIGNATURE' and state='IMMUTABLE';
  if v_candidate_signature.id is null or v_manager_signature.id is null
     or v_candidate_signature.source_content_sha256 is distinct from v_workflow.candidate_signature_sha256
     or v_manager_signature.source_content_sha256 is distinct from v_workflow.manager_signature_sha256
     or not exists(select 1 from public.candidate_approval_requests a
       where a.workflow_id=v_workflow.id and a.workflow_generation=v_workflow.generation
         and a.id=v_manager_signature.approval_request_id and a.method='PHONE' and a.state='APPROVED'
         and a.review_manifest_sha256=v_workflow.review_manifest_sha256)
     or p_electronic_patch is distinct from jsonb_build_object(
       'submission_mode','ELECTRONIC','auth_name',v_workflow.manager_name,
       'auth_job_title',v_workflow.manager_position,
       'r2_nurse_key',v_candidate_signature.storage_key,'r2_auth_key',v_manager_signature.storage_key,
       'img_sha256_nurse',encode(v_candidate_signature.source_content_sha256,'hex'),
       'img_sha256_auth',encode(v_manager_signature.source_content_sha256,'hex'),
       'candidate_workflow_id',v_workflow.id,'candidate_workflow_generation',v_workflow.generation,
       'candidate_manager_approved_at_utc',v_workflow.manager_approved_at_utc) then
    raise exception 'ELECTRONIC_SIGNATURE_PAIR_INCOMPLETE' using errcode='55000';
  end if;

  -- Store only what the Candidate and manager attested. Normal Timesheet
  -- triggers remain enabled and retain their ordinary derived queue work.
  update public.timesheets set
    worked_start_iso=v_start,worked_end_iso=v_end,
    break_start_iso=v_break_start,break_end_iso=v_break_end,
    break_minutes=v_break_minutes,worked_minutes=v_minutes,
    actual_schedule_json=v_patch->'actual_schedule_json',
    submission_mode='ELECTRONIC',candidate_submission_route_intent=null,
    auth_name=v_workflow.manager_name,auth_job_title=v_workflow.manager_position,
    r2_nurse_key=v_candidate_signature.storage_key,r2_auth_key=v_manager_signature.storage_key,
    img_sha256_nurse=encode(v_candidate_signature.source_content_sha256,'hex'),
    img_sha256_auth=encode(v_manager_signature.source_content_sha256,'hex'),
    candidate_workflow_id=v_workflow.id,candidate_workflow_generation=v_workflow.generation,
    candidate_manager_approved_at_utc=v_workflow.manager_approved_at_utc,
    updated_at=p_now_utc
  where timesheet_id=v_timesheet.timesheet_id and is_current and authorised_at_server is null;
  if not found then
    raise exception 'CANDIDATE_RECORD_MUTATION_LOCKED' using errcode='55000';
  end if;
  return jsonb_build_object('ok',true,
    'contract_version','CANDIDATE_DAILY_FACTUAL_RECEIPT_V1',
    'timesheet_id',v_timesheet.timesheet_id,'office_resolution_pending',true,
    'financial_processing_performed',false,'auto_authorised',false);
end;
$function$;

routines.body:
declare
  v_workflow public.candidate_submission_workflows%rowtype;
  v_timesheet public.timesheets%rowtype;
  v_context jsonb;
  v_input jsonb;
  v_patch jsonb;
  v_start timestamptz;
  v_end timestamptz;
  v_break_start timestamptz;
  v_break_end timestamptz;
  v_break_minutes integer;
  v_minutes integer;
  v_candidate_signature public.candidate_submission_components%rowtype;
  v_manager_signature public.candidate_submission_components%rowtype;
begin
  select * into v_workflow from public.candidate_submission_workflows
    where id=p_workflow_id and generation=p_generation for update;
  if not found or v_workflow.workflow_kind<>'DAILY' or v_workflow.scope<>'DAILY'
     or v_workflow.route<>'PHONE' or v_workflow.state<>'READY_TO_FINALISE'
     or v_workflow.contract_week_id is not null or v_workflow.manager_approved_at_utc is null then
    raise exception 'CANDIDATE_DAILY_RECEIPT_NOT_READY' using errcode='55000';
  end if;
  v_context:=private._candidate_daily_receipt_context_v1(
    v_workflow.environment,v_workflow.candidate_id,v_workflow.target_timesheet_id,true,p_now_utc);
  if not coalesce((v_context->>'candidate_first_receipt')::boolean,false)
     or not coalesce((v_context->>'office_resolution_pending')::boolean,false) then
    raise exception 'CANDIDATE_DAILY_RECEIPT_CONTEXT_CHANGED' using errcode='40001';
  end if;
  select * into v_timesheet from public.timesheets
    where timesheet_id=v_workflow.target_timesheet_id and is_current for update;
  if v_timesheet.timesheet_id is null or v_timesheet.authorised_at_server is not null then
    raise exception 'CANDIDATE_RECORD_MUTATION_LOCKED' using errcode='55000';
  end if;
  v_input:=private._candidate_daily_canonical_save_input_v1(v_workflow.id,v_workflow.generation);
  if p_input_sha256_hex is null or p_input_sha256_hex!~'^[a-f0-9]{64}$'
     or encode(private._candidate_sha256_jsonb_v1(v_input),'hex')<>p_input_sha256_hex then
    raise exception 'CANDIDATE_IMMUTABLE_SUBMISSION_MISMATCH' using errcode='40001';
  end if;
  v_patch:=v_input->'timesheet_patch_json';
  v_start:=nullif(v_patch->>'worked_start_iso','')::timestamptz;
  v_end:=nullif(v_patch->>'worked_end_iso','')::timestamptz;
  v_break_start:=nullif(v_patch->>'break_start_iso','')::timestamptz;
  v_break_end:=nullif(v_patch->>'break_end_iso','')::timestamptz;
  v_break_minutes:=nullif(v_patch->>'break_minutes','')::integer;
  if v_start is null or v_end is null or not isfinite(v_start) or not isfinite(v_end)
     or v_end<=v_start or (v_start at time zone 'Europe/London')::date<>v_workflow.work_date
     or (v_end at time zone 'Europe/London')::date not between v_workflow.work_date and v_workflow.work_date+1
     or extract(second from v_start)<>0 or extract(second from v_end)<>0
     or (v_break_start is null)<>(v_break_end is null)
     or (v_break_start is not null and (
       not isfinite(v_break_start) or not isfinite(v_break_end)
       or v_break_start<v_start or v_break_end>v_end or v_break_end<=v_break_start
       or extract(second from v_break_start)<>0 or extract(second from v_break_end)<>0)) then
    raise exception 'CANDIDATE_DAILY_HOURS_INVALID' using errcode='22023';
  end if;
  if v_break_start is not null then
    if v_break_minutes is not null and v_break_minutes<>
        (extract(epoch from (v_break_end-v_break_start))/60)::integer then
      raise exception 'CANDIDATE_DAILY_BREAK_INVALID' using errcode='22023';
    end if;
    v_break_minutes:=(extract(epoch from (v_break_end-v_break_start))/60)::integer;
  end if;
  if v_break_minutes is null or v_break_minutes<0
     or v_break_minutes>=extract(epoch from (v_end-v_start))/60
     or jsonb_typeof(v_patch->'actual_schedule_json') is distinct from 'array'
     or jsonb_array_length(v_patch->'actual_schedule_json')<>1
     or exists(select 1 from jsonb_array_elements(v_patch->'actual_schedule_json') d
       where d->>'date' is distinct from v_workflow.work_date::text) then
    raise exception 'CANDIDATE_DAILY_BREAK_INVALID' using errcode='22023';
  end if;
  v_minutes:=(extract(epoch from (v_end-v_start))/60)::integer-v_break_minutes;
  select * into v_candidate_signature from public.candidate_submission_components
    where id=v_workflow.candidate_signature_component_id and workflow_id=v_workflow.id
      and document_role='CANDIDATE_SIGNATURE' and state='IMMUTABLE';
  select * into v_manager_signature from public.candidate_submission_components
    where id=v_workflow.manager_signature_component_id and workflow_id=v_workflow.id
      and document_role='MANAGER_SIGNATURE' and state='IMMUTABLE';
  if v_candidate_signature.id is null or v_manager_signature.id is null
     or v_candidate_signature.source_content_sha256 is distinct from v_workflow.candidate_signature_sha256
     or v_manager_signature.source_content_sha256 is distinct from v_workflow.manager_signature_sha256
     or not exists(select 1 from public.candidate_approval_requests a
       where a.workflow_id=v_workflow.id and a.workflow_generation=v_workflow.generation
         and a.id=v_manager_signature.approval_request_id and a.method='PHONE' and a.state='APPROVED'
         and a.review_manifest_sha256=v_workflow.review_manifest_sha256)
     or p_electronic_patch is distinct from jsonb_build_object(
       'submission_mode','ELECTRONIC','auth_name',v_workflow.manager_name,
       'auth_job_title',v_workflow.manager_position,
       'r2_nurse_key',v_candidate_signature.storage_key,'r2_auth_key',v_manager_signature.storage_key,
       'img_sha256_nurse',encode(v_candidate_signature.source_content_sha256,'hex'),
       'img_sha256_auth',encode(v_manager_signature.source_content_sha256,'hex'),
       'candidate_workflow_id',v_workflow.id,'candidate_workflow_generation',v_workflow.generation,
       'candidate_manager_approved_at_utc',v_workflow.manager_approved_at_utc) then
    raise exception 'ELECTRONIC_SIGNATURE_PAIR_INCOMPLETE' using errcode='55000';
  end if;

  -- Store only what the Candidate and manager attested. Normal Timesheet
  -- triggers remain enabled and retain their ordinary derived queue work.
  update public.timesheets set
    worked_start_iso=v_start,worked_end_iso=v_end,
    break_start_iso=v_break_start,break_end_iso=v_break_end,
    break_minutes=v_break_minutes,worked_minutes=v_minutes,
    actual_schedule_json=v_patch->'actual_schedule_json',
    submission_mode='ELECTRONIC',candidate_submission_route_intent=null,
    auth_name=v_workflow.manager_name,auth_job_title=v_workflow.manager_position,
    r2_nurse_key=v_candidate_signature.storage_key,r2_auth_key=v_manager_signature.storage_key,
    img_sha256_nurse=encode(v_candidate_signature.source_content_sha256,'hex'),
    img_sha256_auth=encode(v_manager_signature.source_content_sha256,'hex'),
    candidate_workflow_id=v_workflow.id,candidate_workflow_generation=v_workflow.generation,
    candidate_manager_approved_at_utc=v_workflow.manager_approved_at_utc,
    updated_at=p_now_utc
  where timesheet_id=v_timesheet.timesheet_id and is_current and authorised_at_server is null;
  if not found then
    raise exception 'CANDIDATE_RECORD_MUTATION_LOCKED' using errcode='55000';
  end if;
  return jsonb_build_object('ok',true,
    'contract_version','CANDIDATE_DAILY_FACTUAL_RECEIPT_V1',
    'timesheet_id',v_timesheet.timesheet_id,'office_resolution_pending',true,
    'financial_processing_performed',false,'auto_authorised',false);
end;

declare
  v_event text:=upper(btrim(coalesce(p_event,'')));
  v_requested public.timesheets%rowtype;
  v_current public.timesheets%rowtype;
  v_fin public.timesheets_financials%rowtype;
  v_new_timesheet_id uuid;
  v_new_version integer;
  v_audit_actor_user_id uuid;
  v_receipt_context jsonb;
  v_weekly_source_guard jsonb;
begin
  if p_timesheet_id is null
     or p_expected_timesheet_id is null
     or p_actor_user_id is null
     or nullif(btrim(coalesce(p_reason,'')),'') is null
     or v_event not in ('CANDIDATE_WITHDRAWN','OFFICE_REJECTED') then
    raise exception 'CANDIDATE_DAILY_RESET_INVALID' using errcode='22023';
  end if;

  select requested_row.* into v_requested
  from public.timesheets requested_row
  where requested_row.timesheet_id=p_timesheet_id;
  if not found
     or v_requested.sheet_scope<>'DAILY'::public.timesheet_scope_enum
     or nullif(btrim(coalesce(v_requested.booking_id,'')),'') is null then
    raise exception 'CANDIDATE_DAILY_RESET_TARGET_NOT_FOUND' using errcode='P0002';
  end if;

  select current_row.* into v_current
  from public.timesheets current_row
  where current_row.booking_id=v_requested.booking_id
    and current_row.is_current=true
    and current_row.archived_at_utc is null
    and current_row.sheet_scope='DAILY'::public.timesheet_scope_enum
  for update;
  if not found or v_current.timesheet_id is distinct from p_expected_timesheet_id then
    raise exception 'TIMESHEET_MOVED' using errcode='40001';
  end if;

  -- Prove the same Candidate/environment even when the existing financial
  -- reset owner will perform the rotation. Do not delegate a foreign target.
  if v_event='OFFICE_REJECTED' and not private._candidate_office_service_context_valid_v1(
    p_environment,p_actor_user_id,'REJECT_CONFIRM') then
    raise exception 'CANDIDATE_OFFICE_SERVICE_CONTEXT_REQUIRED' using errcode='28000';
  end if;
  v_receipt_context:=private._candidate_daily_receipt_context_v1(
    p_environment,p_candidate_id,v_current.timesheet_id,
    v_event<>'OFFICE_REJECTED',p_now_utc);
  select financial_row.* into v_fin
  from public.timesheets_financials financial_row
  where financial_row.timesheet_id=v_current.timesheet_id
    and financial_row.is_current=true
  order by financial_row.computed_at_utc desc nulls last,
    financial_row.updated_at desc,financial_row.id desc
  limit 1
  for update;
  if v_current.authorised_at_server is not null
     or v_fin.authorised_at_utc is not null or v_fin.paid_at_utc is not null
     or v_fin.locked_by_invoice_id is not null then
    raise exception 'CANDIDATE_DAILY_RESET_PROTECTED_HISTORY' using errcode='55000';
  end if;
  if coalesce((v_receipt_context->>'import_authoritative')::boolean,false)
     or v_current.qr_status is not null or v_current.qr_token is not null
     or v_current.qr_r2_key is not null
     or (v_current.submission_mode<>'ELECTRONIC'
       and v_current.candidate_submission_route_intent is distinct from 'ELECTRONIC') then
    raise exception 'CANDIDATE_RECORD_VIEW_ONLY' using errcode='55000';
  end if;
  if v_fin.id is not null then
    -- Keep the existing financial/history owner byte-for-byte unchanged.
    return private._candidate_daily_submission_reset_v1(p_timesheet_id,p_expected_timesheet_id,
      p_reason,p_actor_user_id,p_event,p_now_utc);
  end if;
  if not coalesce((v_receipt_context->>'candidate_first_receipt')::boolean,false) then
    raise exception 'CANDIDATE_DAILY_FINANCIALS_NOT_FOUND' using errcode='P0002';
  end if;
  if v_current.authorised_at_server is not null
     or v_fin.authorised_at_utc is not null
     or v_fin.paid_at_utc is not null
     or v_fin.locked_by_invoice_id is not null then
    raise exception 'CANDIDATE_DAILY_RESET_PROTECTED_HISTORY' using errcode='55000';
  end if;

  -- Plan 6.2 G6-11 (proof/34 section 3, entry point E10): refuse for an
  -- authorised Weekly-Source-managed root, before this owner's first write and
  -- while it holds the current timesheet and TSFIN row locks taken above.  An
  -- unmanaged family is unaffected.
  v_weekly_source_guard:=private.weekly_source_managed_root_guard_v1(
    v_current.timesheet_id
  );
  -- HANDOVER 2 round-5 ruling B3 and A4 (18 September 2026).  The refusal is
  -- NARROWED: it applies to a Weekly-Source managed root, to a bound or
  -- protected family whose identity cannot be resolved, to a family carrying
  -- protected pay evidence but no authorisation row
  -- (PROTECTED_ROOT_AUTHORITY_MISSING), and to the live-record-on-an-
  -- unauthorised-Timesheet contradiction, which must never be allowed to
  -- continue merely because managed is false.  An unrelated, UNBOUND ordinary
  -- family -- including a malformed one -- keeps exactly the behaviour it had
  -- before this feature was installed.  Absent, null and non-boolean take the
  -- unsafe value at every read (Part 1 addendum rule 4).
  if (coalesce((v_weekly_source_guard->>'managed')::boolean, true)
       and (coalesce((v_weekly_source_guard->>'ok')::boolean, true)
            or coalesce((v_weekly_source_guard->>'weekly_source_bound')::boolean, true)))
     or coalesce((v_weekly_source_guard->>'authorisation_record_without_authorised_timesheet')::boolean, false)
     or (v_weekly_source_guard->>'protected_target_ownership_state') is not null then
    raise exception 'WEEKLY_SOURCE_MANAGED_ROOT_ROTATION_REFUSED'
      using errcode='55000',detail=jsonb_build_object(
        'code','WEEKLY_SOURCE_MANAGED_ROOT_ROTATION_REFUSED',
        'entry_point','E10:private._candidate_daily_receipt_reset_v1',
        'block_reason','WEEKLY_SOURCE_MANAGED_ROOT',
        'refusal_basis', case
          -- HANDOVER 2 round-5 Part E: the trim-equivalent split family is a
          -- canonical booking-reference collision and must be named as one.
          -- WP-03 handoff N20: accept BOTH the installed token and the ruled name for one
          -- release, so the order of this edit and WP-03's rename cannot open a gap in
          -- which Office stops seeing the ruled name.
          when v_weekly_source_guard->>'reason' in (
                 'FAMILY_SPLIT_BY_WHITESPACE','BOOKING_REFERENCE_CANONICAL_COLLISION')
            then 'BOOKING_REFERENCE_CANONICAL_COLLISION'
          when coalesce((v_weekly_source_guard->>'managed')::boolean, true) and coalesce((v_weekly_source_guard->>'ok')::boolean, true)
            then 'WEEKLY_SOURCE_MANAGED_ROOT'
          when coalesce((v_weekly_source_guard->>'managed')::boolean, true)
            then 'WEEKLY_SOURCE_BOUND_OR_PROTECTED_ROOT_UNRESOLVABLE'
          when coalesce((v_weekly_source_guard->>'authorisation_record_without_authorised_timesheet')::boolean, false)
            then 'AUTHORISATION_RECORD_WITHOUT_AUTHORISED_TIMESHEET'
          else 'PROTECTED_ROOT_AUTHORITY_MISSING' end,
        'integrity_failure', not coalesce((v_weekly_source_guard->>'ok')::boolean,false),
        'timesheet_id',v_current.timesheet_id,
        'reason',v_weekly_source_guard->>'reason'
      )::text;
  end if;

  v_new_version:=coalesce(v_current.version,1)+1;
  update public.timesheets set
    is_current=false,
    status='REVOKED',
    revoked_at=p_now_utc,
    revoked_reason=btrim(p_reason),
    revoked_by=p_actor_user_id::text,
    updated_at=p_now_utc
  where timesheet_id=v_current.timesheet_id and is_current=true;

  insert into public.timesheets(
    booking_id,version,is_current,status,contract_id,submission_mode,line_type,sheet_scope,
    occupant_key_norm,hospital_norm,ward_norm,job_title_norm,shift_label_norm,band,
    scheduled_start_iso,scheduled_end_iso,week_ending_date,
    worked_start_iso,worked_end_iso,break_start_iso,break_end_iso,break_minutes,worked_minutes,
    actual_schedule_json,additional_units_week,additional_units_per_day,
    manual_pdf_r2_key,authorised_at_server,reference_number,day_references_json,
    qr_token,qr_status,qr_payload_json,qr_generated_at,qr_scanned_at,qr_scan_info_json,qr_r2_key,
    candidate_hint_text,candidate_submission_route_intent,created_at,updated_at
  ) values (
    v_current.booking_id,v_new_version,true,'RECEIVED',v_current.contract_id,'MANUAL',
    v_current.line_type,v_current.sheet_scope,v_current.occupant_key_norm,
    v_current.hospital_norm,v_current.ward_norm,v_current.job_title_norm,
    v_current.shift_label_norm,v_current.band,v_current.scheduled_start_iso,
    v_current.scheduled_end_iso,v_current.week_ending_date,
    null,null,null,null,null,null,null,'{}'::jsonb,'{}'::jsonb,
    null,null,null,null,null,null,'{}'::jsonb,null,null,null,null,
    v_current.candidate_hint_text,'ELECTRONIC',p_now_utc,p_now_utc
  ) returning timesheet_id into v_new_timesheet_id;

  -- No financial snapshot exists in this receipt-only branch. Do not
  -- fabricate one merely to rotate the same current booking family.

  update public.timesheet_evidence set processing_state='SUPERSEDED'
  where timesheet_id=v_current.timesheet_id and processing_state<>'SUPERSEDED';

  if v_event='OFFICE_REJECTED' then
    select actor_row.id into v_audit_actor_user_id
    from public.tms_users actor_row
    where actor_row.id=p_actor_user_id;
  else
    select settings_row.candidate_app_system_actor_user_id
    into v_audit_actor_user_id
    from public.settings_defaults settings_row
    where settings_row.id=1;
  end if;
  if v_audit_actor_user_id is null then
    raise exception 'CANDIDATE_SYSTEM_ACTOR_REQUIRED' using errcode='55000';
  end if;

  perform private._candidate_audit_v1(
    'timesheet',v_new_timesheet_id::text,
    case when v_event='OFFICE_REJECTED'
      then 'CANDIDATE_DAILY_RECEIPT_REJECTED_VERSION_ROTATED'
      else 'CANDIDATE_DAILY_RECEIPT_WITHDRAWN_VERSION_ROTATED' end,
    jsonb_build_object(
      'old_timesheet_id',v_current.timesheet_id,
      'old_version',v_current.version,
      'previous_submission_mode',v_current.submission_mode
    ),
    jsonb_build_object(
      'new_timesheet_id',v_new_timesheet_id,
      'new_version',v_new_version,
      'candidate_submission_route_intent','ELECTRONIC'
    ),
    btrim(p_reason),v_audit_actor_user_id,null,p_now_utc
  );

  return jsonb_build_object(
    'reset',true,
    'scope','DAILY',
    'event',v_event,
    'old_timesheet_id',v_current.timesheet_id,
    'current_timesheet_id',v_new_timesheet_id,
    'timesheet_version',v_new_version,
    'draft_submission_mode','MANUAL',
    'effective_submission_mode','ELECTRONIC'
  );
end;

