CREATE OR REPLACE FUNCTION public.timesheet_daily_manual_process_atomic(p_timesheet_id uuid, p_expected_timesheet_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_timesheet_patch_json jsonb DEFAULT '{}'::jsonb, p_tsfin_patch_json jsonb DEFAULT '{}'::jsonb, p_now_utc timestamp with time zone DEFAULT now(), p_expected_row_signature text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamp with time zone := COALESCE(p_now_utc, now());
  v_requested_ts public.timesheets%ROWTYPE;
  v_current_ts public.timesheets%ROWTYPE;
  v_current_tsfin public.timesheets_financials%ROWTYPE;
  v_previous_status public.ts_fin_processing_status_enum := NULL;
  v_new_status public.ts_fin_processing_status_enum := 'PENDING_AUTH'::public.ts_fin_processing_status_enum;
  v_has_segment_invoice_lock boolean := false;
  v_timesheet_patch jsonb := COALESCE(p_timesheet_patch_json, '{}'::jsonb);
  v_tsfin_patch jsonb := COALESCE(p_tsfin_patch_json, '{}'::jsonb);
  v_forbidden_tsfin_patch_keys text[] := ARRAY[
    'candidate_id','client_id','pay_method','candidate_assignment','basis','policy_snapshot_json','rate_source_refs_json',
    'normal_hours','unsocial_hours','saturday_hours','sunday_hours','bank_holiday_hours','sleep_in_units','on_call_units','mileage_units','expenses_units',
    'total_hours','total_pay_ex_vat','total_charge_ex_vat','margin_ex_vat','net_delta_ex_vat','normal_pay_rate','unsocial_pay_rate','saturday_pay_rate','sunday_pay_rate','bank_holiday_pay_rate',
    'normal_charge_rate','unsocial_charge_rate','saturday_charge_rate','sunday_charge_rate','bank_holiday_charge_rate','mileage_pay_rate','mileage_charge_rate','expenses_pay','expenses_charge',
    'has_rate_issue','has_pay_channel_issue','hours_day','hours_night','hours_sat','hours_sun','hours_bh','pay_day','pay_night','pay_sat','pay_sun','pay_bh','charge_day','charge_night','charge_sat','charge_sun','charge_bh',
    'expenses_pay_ex_vat','expenses_charge_ex_vat','mileage_pay_ex_vat','mileage_charge_ex_vat','travel_pay_ex_vat','travel_charge_ex_vat','accommodation_pay_ex_vat','accommodation_charge_ex_vat','other_pay_ex_vat','other_charge_ex_vat','additional_pay_ex_vat','additional_charge_ex_vat','additional_margin_ex_vat'
  ];
  v_financial_affecting_timesheet_patch_keys text[] := ARRAY[
    'worked_start_iso','worked_end_iso','break_start_iso','break_end_iso','break_minutes','worked_minutes','actual_schedule_json','additional_units_week','additional_units_per_day','scheduled_start_iso','scheduled_end_iso','week_ending_date','worked_date','work_date'
  ];
  v_patch_key text := NULL;
  v_before_signature_json jsonb := '{}'::jsonb;
  v_after_signature_json jsonb := '{}'::jsonb;
  v_current_row_signature text := NULL;
  v_expected_row_signature text := NULL;
  v_after_row_signature text := NULL;
  v_error_state text := NULL;
  v_error_message text := NULL;
  v_candidate_electronic_context boolean :=
    COALESCE(current_setting('cloudtms.candidate_electronic_finalise', true), '') <> ''
    AND private._candidate_feature_enabled_current_v1('candidate_daily_finalisation');
BEGIN
  PERFORM set_config('lock_timeout', '2500ms', true);

  IF p_timesheet_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_ID_REQUIRED', 'message', 'p_timesheet_id is required.');
  END IF;
  IF p_expected_timesheet_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'EXPECTED_TIMESHEET_ID_REQUIRED', 'message', 'p_expected_timesheet_id is required.');
  END IF;
  IF p_actor_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'ACTOR_USER_ID_REQUIRED', 'message', 'p_actor_user_id is required.');
  END IF;
  IF jsonb_typeof(v_timesheet_patch) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_PATCH_MUST_BE_OBJECT', 'message', 'p_timesheet_patch_json must be a JSON object.');
  END IF;
  IF jsonb_typeof(v_tsfin_patch) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'TSFIN_PATCH_MUST_BE_OBJECT', 'message', 'p_tsfin_patch_json must be a JSON object.');
  END IF;

  IF NOT v_candidate_electronic_context
     AND v_timesheet_patch ?| ARRAY[
       'submission_mode','auth_name','auth_job_title','r2_nurse_key','r2_auth_key',
       'img_sha256_nurse','img_sha256_auth','candidate_workflow_id',
       'candidate_workflow_generation','candidate_manager_approved_at_utc'
     ] THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process',
      'error_code', 'CANDIDATE_ELECTRONIC_FIELDS_FORBIDDEN',
      'message', 'Candidate electronic document fields require the bounded Candidate App finalisation authority.');
  END IF;

  FOREACH v_patch_key IN ARRAY v_forbidden_tsfin_patch_keys LOOP
    IF v_tsfin_patch ? v_patch_key THEN
      RETURN jsonb_build_object('ok', false, 'success', false, 'operation', 'daily_manual_process', 'error_code', 'TSFIN_PATCH_FORBIDDEN_FIELD', 'message', 'Cannot process: TSFIN patch contains an authoritative or financial field.', 'field', v_patch_key, 'timesheet_id', p_timesheet_id);
    END IF;
  END LOOP;

  FOREACH v_patch_key IN ARRAY v_financial_affecting_timesheet_patch_keys LOOP
    IF v_timesheet_patch ? v_patch_key THEN
      RETURN jsonb_build_object('ok', false, 'success', false, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_PATCH_REQUIRES_RECALCULATION', 'message', 'Cannot process while changing worked time, schedule, break, work date, or additional units. Save and recalculate the row before processing.', 'field', v_patch_key, 'timesheet_id', p_timesheet_id);
    END IF;
  END LOOP;

  SELECT ts.*
    INTO v_requested_ts
  FROM public.timesheets AS ts
  WHERE ts.timesheet_id = p_timesheet_id
  LIMIT 1;

  IF v_requested_ts.timesheet_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_NOT_FOUND', 'message', 'Timesheet was not found.', 'requested_timesheet_id', p_timesheet_id);
  END IF;

  SELECT ts.*
    INTO v_current_ts
  FROM public.timesheets AS ts
  WHERE ts.booking_id = v_requested_ts.booking_id
    AND ts.is_current = true
  ORDER BY ts.version DESC NULLS LAST, ts.updated_at DESC NULLS LAST, ts.created_at DESC NULLS LAST, ts.timesheet_id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_current_ts.timesheet_id IS NULL THEN
    v_current_ts := v_requested_ts;
  END IF;

  IF p_expected_timesheet_id IS DISTINCT FROM v_current_ts.timesheet_id THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_MOVED', 'message', 'Timesheet has moved to a newer current row.', 'requested_timesheet_id', p_timesheet_id, 'expected_timesheet_id', p_expected_timesheet_id, 'current_timesheet_id', v_current_ts.timesheet_id, 'was_stale', v_requested_ts.timesheet_id IS DISTINCT FROM v_current_ts.timesheet_id);
  END IF;

  IF v_current_ts.sheet_scope <> 'DAILY'::public.timesheet_scope_enum THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'NOT_DAILY', 'message', 'Timesheet is not DAILY; daily manual process only applies to DAILY sheets.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;
  IF v_current_ts.submission_mode <> 'MANUAL'::public.submission_mode_enum
     AND NOT (v_candidate_electronic_context
       AND v_current_ts.submission_mode = 'ELECTRONIC'::public.submission_mode_enum) THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'NOT_MANUAL', 'message', 'Timesheet must be MANUAL before processing.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;
  IF v_current_ts.archived_at_utc IS NOT NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'TIMESHEET_ARCHIVED', DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id)::text;
  END IF;

  IF v_current_ts.authorised_at_server IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_ALREADY_AUTHORISED', 'message', 'This timesheet is already authorised.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;

  SELECT tf.*
    INTO v_current_tsfin
  FROM public.timesheets_financials AS tf
  WHERE tf.timesheet_id = v_current_ts.timesheet_id
    AND tf.is_current = true
  ORDER BY tf.computed_at_utc DESC NULLS LAST, tf.created_at DESC NULLS LAST, tf.updated_at DESC NULLS LAST, tf.id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_current_tsfin.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'NO_TSFIN', 'message', 'No current financial snapshot exists for this timesheet.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;

  v_previous_status := v_current_tsfin.processing_status;
  SELECT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(
      CASE
        WHEN v_current_tsfin.invoice_breakdown_json IS NULL THEN '[]'::jsonb
        WHEN jsonb_typeof(v_current_tsfin.invoice_breakdown_json) = 'array' THEN v_current_tsfin.invoice_breakdown_json
        WHEN jsonb_typeof(v_current_tsfin.invoice_breakdown_json) = 'object'
         AND jsonb_typeof(v_current_tsfin.invoice_breakdown_json -> 'segments') = 'array' THEN v_current_tsfin.invoice_breakdown_json -> 'segments'
        ELSE '[]'::jsonb
      END
    ) AS invoice_segment(segment_json)
    WHERE NULLIF(BTRIM(COALESCE(invoice_segment.segment_json ->> 'invoice_locked_invoice_id', '')), '') IS NOT NULL
  ) INTO v_has_segment_invoice_lock;

  IF v_current_tsfin.locked_by_invoice_id IS NOT NULL OR COALESCE(v_has_segment_invoice_lock, false) THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_LOCKED_BY_INVOICE', 'message', 'Timesheet is invoice-locked; cannot process.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;
  IF v_previous_status <> 'UNPROCESSED'::public.ts_fin_processing_status_enum THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'NOT_UNPROCESSED', 'message', 'Timesheet is not in UNPROCESSED state.', 'current_timesheet_id', v_current_ts.timesheet_id, 'previous_status', v_previous_status::text);
  END IF;
  IF v_current_tsfin.candidate_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'CANDIDATE_MISSING', 'message', 'Cannot process: candidate is missing from TSFIN context.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;
  IF v_current_tsfin.client_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'CLIENT_MISSING', 'message', 'Cannot process: client is missing from TSFIN context.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;
  IF COALESCE(v_current_tsfin.has_rate_issue, false) THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'RATE_ISSUE', 'message', 'Cannot process: TSFIN has a rate issue.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;
  IF COALESCE(v_current_tsfin.has_pay_channel_issue, false) THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'PAY_CHANNEL_ISSUE', 'message', 'Cannot process: TSFIN has a pay channel issue.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_current_tsfin.pay_method, '')), '') IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'PAY_METHOD_MISSING', 'message', 'Cannot process: pay method is missing from TSFIN context.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;
  IF v_current_tsfin.candidate_assignment = 'UNASSIGNED'::public.candidate_assignment_enum THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'CANDIDATE_ASSIGNMENT_UNRESOLVED', 'message', 'Cannot process: candidate assignment is unresolved in TSFIN context.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;

  v_before_signature_json := public.timesheet_lifecycle_signature_v1(v_current_ts.timesheet_id, NULL::uuid, false);
  v_current_row_signature := NULLIF(BTRIM(COALESCE(v_before_signature_json ->> 'backend_row_signature', v_before_signature_json ->> 'row_signature', v_before_signature_json ->> 'signature', '')), '');
  v_expected_row_signature := NULLIF(BTRIM(COALESCE(p_expected_row_signature, v_timesheet_patch ->> 'backend_row_signature', v_timesheet_patch ->> 'row_signature', v_tsfin_patch ->> 'backend_row_signature', v_tsfin_patch ->> 'row_signature', '')), '');

  IF v_expected_row_signature IS NOT NULL AND COALESCE(v_current_row_signature, '') IS DISTINCT FROM v_expected_row_signature THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'ROW_SIGNATURE_MISMATCH', 'message', 'Timesheet changed after it was loaded. Refresh the row and try again.', 'current_timesheet_id', v_current_ts.timesheet_id, 'expected_row_signature', v_expected_row_signature, 'current_row_signature', v_current_row_signature);
  END IF;

  UPDATE public.timesheets AS ts
     SET reference_number = CASE WHEN v_timesheet_patch ? 'reference_number' THEN NULLIF(BTRIM(v_timesheet_patch ->> 'reference_number'), '') ELSE ts.reference_number END,
         reference_set_at = CASE
           WHEN v_timesheet_patch ? 'reference_number' THEN
             CASE WHEN NULLIF(BTRIM(v_timesheet_patch ->> 'reference_number'), '') IS NULL THEN NULL::timestamp with time zone
                  WHEN NULLIF(BTRIM(v_timesheet_patch ->> 'reference_number'), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(ts.reference_number, '')), '') THEN v_now
                  ELSE COALESCE(ts.reference_set_at, v_now)
             END
           ELSE ts.reference_set_at
         END,
         submission_mode = CASE WHEN v_candidate_electronic_context
           THEN 'ELECTRONIC'::public.submission_mode_enum ELSE ts.submission_mode END,
         auth_name = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(BTRIM(v_timesheet_patch->>'auth_name'),'') ELSE ts.auth_name END,
         auth_job_title = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(BTRIM(v_timesheet_patch->>'auth_job_title'),'') ELSE ts.auth_job_title END,
         r2_nurse_key = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(BTRIM(v_timesheet_patch->>'r2_nurse_key'),'') ELSE ts.r2_nurse_key END,
         r2_auth_key = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(BTRIM(v_timesheet_patch->>'r2_auth_key'),'') ELSE ts.r2_auth_key END,
         img_sha256_nurse = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(BTRIM(v_timesheet_patch->>'img_sha256_nurse'),'') ELSE ts.img_sha256_nurse END,
         img_sha256_auth = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(BTRIM(v_timesheet_patch->>'img_sha256_auth'),'') ELSE ts.img_sha256_auth END,
         candidate_workflow_id = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(v_timesheet_patch->>'candidate_workflow_id','')::uuid ELSE ts.candidate_workflow_id END,
         candidate_workflow_generation = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(v_timesheet_patch->>'candidate_workflow_generation','')::integer ELSE ts.candidate_workflow_generation END,
         candidate_manager_approved_at_utc = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(v_timesheet_patch->>'candidate_manager_approved_at_utc','')::timestamptz
           ELSE ts.candidate_manager_approved_at_utc END,
         updated_at = v_now
   WHERE ts.timesheet_id = v_current_ts.timesheet_id
     AND ts.is_current = true
   RETURNING * INTO v_current_ts;

  UPDATE public.timesheets_financials AS tf
     SET processing_status = v_new_status,
         processed_by_user_id = p_actor_user_id,
         processed_at_utc = v_now,
         authorised_by_user_id = NULL,
         authorised_at_utc = NULL,
         updated_at = v_now
   WHERE tf.id = v_current_tsfin.id
     AND tf.is_current = true
   RETURNING * INTO v_current_tsfin;

  v_after_signature_json := public.timesheet_lifecycle_signature_v1(v_current_ts.timesheet_id, NULL::uuid, false);
  v_after_row_signature := NULLIF(BTRIM(COALESCE(v_after_signature_json ->> 'backend_row_signature', v_after_signature_json ->> 'row_signature', v_after_signature_json ->> 'signature', '')), '');

  PERFORM public._audit_insert(
    'timesheet',
    v_current_ts.timesheet_id::text,
    'TIMESHEET_DAILY_MANUAL_PROCESSED',
    jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'previous_processing_status', v_previous_status::text, 'previous_row_signature', v_current_row_signature),
    jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'new_processing_status', v_new_status::text, 'processed_at_utc', v_now, 'processed_by_user_id', p_actor_user_id, 'new_row_signature', v_after_row_signature),
    'DAILY_MANUAL_PROCESS',
    p_actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'success', true,
    'operation', 'daily_manual_process',
    'processed', true,
    'requested_timesheet_id', p_timesheet_id,
    'expected_timesheet_id', p_expected_timesheet_id,
    'current_timesheet_id', v_current_ts.timesheet_id,
    'timesheet_id', v_current_ts.timesheet_id,
    'timesheet_financials_id', v_current_tsfin.id,
    'current_version', v_current_ts.version,
    'was_stale', v_requested_ts.timesheet_id IS DISTINCT FROM v_current_ts.timesheet_id,
    'previous_status', v_previous_status::text,
    'processing_status', v_new_status::text,
    'new_processing_status', v_new_status::text,
    'backend_row_signature', v_after_row_signature,
    'row_signature', v_after_row_signature,
    'status_transition', jsonb_build_object('from', v_previous_status::text, 'to', v_new_status::text, 'processed_at_utc', v_now, 'processed_by_user_id', p_actor_user_id),
    'affected_rows', jsonb_build_array(jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'row_key', 'timesheet:' || v_current_ts.timesheet_id::text)),
    'count_deltas', jsonb_build_object('unprocessed', -1, 'processed', 1),
    'cache_invalidation_hints', jsonb_build_object('changed_domains', jsonb_build_array('timesheets', 'timesheets_financials'), 'timesheet_id', v_current_ts.timesheet_id)
  );
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS v_error_state = RETURNED_SQLSTATE, v_error_message = MESSAGE_TEXT;
  IF v_error_state = '55P03' THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'LOCK_TIMEOUT', 'message', 'The timesheet is currently locked by another operation.', 'timesheet_id', p_timesheet_id);
  END IF;
  RAISE;
END;
$function$;

routines.body:
DECLARE
  v_now timestamp with time zone := COALESCE(p_now_utc, now());
  v_requested_ts public.timesheets%ROWTYPE;
  v_current_ts public.timesheets%ROWTYPE;
  v_current_tsfin public.timesheets_financials%ROWTYPE;
  v_previous_status public.ts_fin_processing_status_enum := NULL;
  v_new_status public.ts_fin_processing_status_enum := 'PENDING_AUTH'::public.ts_fin_processing_status_enum;
  v_has_segment_invoice_lock boolean := false;
  v_timesheet_patch jsonb := COALESCE(p_timesheet_patch_json, '{}'::jsonb);
  v_tsfin_patch jsonb := COALESCE(p_tsfin_patch_json, '{}'::jsonb);
  v_forbidden_tsfin_patch_keys text[] := ARRAY[
    'candidate_id','client_id','pay_method','candidate_assignment','basis','policy_snapshot_json','rate_source_refs_json',
    'normal_hours','unsocial_hours','saturday_hours','sunday_hours','bank_holiday_hours','sleep_in_units','on_call_units','mileage_units','expenses_units',
    'total_hours','total_pay_ex_vat','total_charge_ex_vat','margin_ex_vat','net_delta_ex_vat','normal_pay_rate','unsocial_pay_rate','saturday_pay_rate','sunday_pay_rate','bank_holiday_pay_rate',
    'normal_charge_rate','unsocial_charge_rate','saturday_charge_rate','sunday_charge_rate','bank_holiday_charge_rate','mileage_pay_rate','mileage_charge_rate','expenses_pay','expenses_charge',
    'has_rate_issue','has_pay_channel_issue','hours_day','hours_night','hours_sat','hours_sun','hours_bh','pay_day','pay_night','pay_sat','pay_sun','pay_bh','charge_day','charge_night','charge_sat','charge_sun','charge_bh',
    'expenses_pay_ex_vat','expenses_charge_ex_vat','mileage_pay_ex_vat','mileage_charge_ex_vat','travel_pay_ex_vat','travel_charge_ex_vat','accommodation_pay_ex_vat','accommodation_charge_ex_vat','other_pay_ex_vat','other_charge_ex_vat','additional_pay_ex_vat','additional_charge_ex_vat','additional_margin_ex_vat'
  ];
  v_financial_affecting_timesheet_patch_keys text[] := ARRAY[
    'worked_start_iso','worked_end_iso','break_start_iso','break_end_iso','break_minutes','worked_minutes','actual_schedule_json','additional_units_week','additional_units_per_day','scheduled_start_iso','scheduled_end_iso','week_ending_date','worked_date','work_date'
  ];
  v_patch_key text := NULL;
  v_before_signature_json jsonb := '{}'::jsonb;
  v_after_signature_json jsonb := '{}'::jsonb;
  v_current_row_signature text := NULL;
  v_expected_row_signature text := NULL;
  v_after_row_signature text := NULL;
  v_error_state text := NULL;
  v_error_message text := NULL;
  v_candidate_electronic_context boolean :=
    COALESCE(current_setting('cloudtms.candidate_electronic_finalise', true), '') <> ''
    AND private._candidate_feature_enabled_current_v1('candidate_daily_finalisation');
BEGIN
  PERFORM set_config('lock_timeout', '2500ms', true);

  IF p_timesheet_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_ID_REQUIRED', 'message', 'p_timesheet_id is required.');
  END IF;
  IF p_expected_timesheet_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'EXPECTED_TIMESHEET_ID_REQUIRED', 'message', 'p_expected_timesheet_id is required.');
  END IF;
  IF p_actor_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'ACTOR_USER_ID_REQUIRED', 'message', 'p_actor_user_id is required.');
  END IF;
  IF jsonb_typeof(v_timesheet_patch) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_PATCH_MUST_BE_OBJECT', 'message', 'p_timesheet_patch_json must be a JSON object.');
  END IF;
  IF jsonb_typeof(v_tsfin_patch) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'TSFIN_PATCH_MUST_BE_OBJECT', 'message', 'p_tsfin_patch_json must be a JSON object.');
  END IF;

  IF NOT v_candidate_electronic_context
     AND v_timesheet_patch ?| ARRAY[
       'submission_mode','auth_name','auth_job_title','r2_nurse_key','r2_auth_key',
       'img_sha256_nurse','img_sha256_auth','candidate_workflow_id',
       'candidate_workflow_generation','candidate_manager_approved_at_utc'
     ] THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process',
      'error_code', 'CANDIDATE_ELECTRONIC_FIELDS_FORBIDDEN',
      'message', 'Candidate electronic document fields require the bounded Candidate App finalisation authority.');
  END IF;

  FOREACH v_patch_key IN ARRAY v_forbidden_tsfin_patch_keys LOOP
    IF v_tsfin_patch ? v_patch_key THEN
      RETURN jsonb_build_object('ok', false, 'success', false, 'operation', 'daily_manual_process', 'error_code', 'TSFIN_PATCH_FORBIDDEN_FIELD', 'message', 'Cannot process: TSFIN patch contains an authoritative or financial field.', 'field', v_patch_key, 'timesheet_id', p_timesheet_id);
    END IF;
  END LOOP;

  FOREACH v_patch_key IN ARRAY v_financial_affecting_timesheet_patch_keys LOOP
    IF v_timesheet_patch ? v_patch_key THEN
      RETURN jsonb_build_object('ok', false, 'success', false, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_PATCH_REQUIRES_RECALCULATION', 'message', 'Cannot process while changing worked time, schedule, break, work date, or additional units. Save and recalculate the row before processing.', 'field', v_patch_key, 'timesheet_id', p_timesheet_id);
    END IF;
  END LOOP;

  SELECT ts.*
    INTO v_requested_ts
  FROM public.timesheets AS ts
  WHERE ts.timesheet_id = p_timesheet_id
  LIMIT 1;

  IF v_requested_ts.timesheet_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_NOT_FOUND', 'message', 'Timesheet was not found.', 'requested_timesheet_id', p_timesheet_id);
  END IF;

  SELECT ts.*
    INTO v_current_ts
  FROM public.timesheets AS ts
  WHERE ts.booking_id = v_requested_ts.booking_id
    AND ts.is_current = true
  ORDER BY ts.version DESC NULLS LAST, ts.updated_at DESC NULLS LAST, ts.created_at DESC NULLS LAST, ts.timesheet_id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_current_ts.timesheet_id IS NULL THEN
    v_current_ts := v_requested_ts;
  END IF;

  IF p_expected_timesheet_id IS DISTINCT FROM v_current_ts.timesheet_id THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_MOVED', 'message', 'Timesheet has moved to a newer current row.', 'requested_timesheet_id', p_timesheet_id, 'expected_timesheet_id', p_expected_timesheet_id, 'current_timesheet_id', v_current_ts.timesheet_id, 'was_stale', v_requested_ts.timesheet_id IS DISTINCT FROM v_current_ts.timesheet_id);
  END IF;

  IF v_current_ts.sheet_scope <> 'DAILY'::public.timesheet_scope_enum THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'NOT_DAILY', 'message', 'Timesheet is not DAILY; daily manual process only applies to DAILY sheets.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;
  IF v_current_ts.submission_mode <> 'MANUAL'::public.submission_mode_enum
     AND NOT (v_candidate_electronic_context
       AND v_current_ts.submission_mode = 'ELECTRONIC'::public.submission_mode_enum) THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'NOT_MANUAL', 'message', 'Timesheet must be MANUAL before processing.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;
  IF v_current_ts.archived_at_utc IS NOT NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'TIMESHEET_ARCHIVED', DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id)::text;
  END IF;

  IF v_current_ts.authorised_at_server IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_ALREADY_AUTHORISED', 'message', 'This timesheet is already authorised.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;

  SELECT tf.*
    INTO v_current_tsfin
  FROM public.timesheets_financials AS tf
  WHERE tf.timesheet_id = v_current_ts.timesheet_id
    AND tf.is_current = true
  ORDER BY tf.computed_at_utc DESC NULLS LAST, tf.created_at DESC NULLS LAST, tf.updated_at DESC NULLS LAST, tf.id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_current_tsfin.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'NO_TSFIN', 'message', 'No current financial snapshot exists for this timesheet.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;

  v_previous_status := v_current_tsfin.processing_status;
  SELECT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(
      CASE
        WHEN v_current_tsfin.invoice_breakdown_json IS NULL THEN '[]'::jsonb
        WHEN jsonb_typeof(v_current_tsfin.invoice_breakdown_json) = 'array' THEN v_current_tsfin.invoice_breakdown_json
        WHEN jsonb_typeof(v_current_tsfin.invoice_breakdown_json) = 'object'
         AND jsonb_typeof(v_current_tsfin.invoice_breakdown_json -> 'segments') = 'array' THEN v_current_tsfin.invoice_breakdown_json -> 'segments'
        ELSE '[]'::jsonb
      END
    ) AS invoice_segment(segment_json)
    WHERE NULLIF(BTRIM(COALESCE(invoice_segment.segment_json ->> 'invoice_locked_invoice_id', '')), '') IS NOT NULL
  ) INTO v_has_segment_invoice_lock;

  IF v_current_tsfin.locked_by_invoice_id IS NOT NULL OR COALESCE(v_has_segment_invoice_lock, false) THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_LOCKED_BY_INVOICE', 'message', 'Timesheet is invoice-locked; cannot process.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;
  IF v_previous_status <> 'UNPROCESSED'::public.ts_fin_processing_status_enum THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'NOT_UNPROCESSED', 'message', 'Timesheet is not in UNPROCESSED state.', 'current_timesheet_id', v_current_ts.timesheet_id, 'previous_status', v_previous_status::text);
  END IF;
  IF v_current_tsfin.candidate_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'CANDIDATE_MISSING', 'message', 'Cannot process: candidate is missing from TSFIN context.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;
  IF v_current_tsfin.client_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'CLIENT_MISSING', 'message', 'Cannot process: client is missing from TSFIN context.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;
  IF COALESCE(v_current_tsfin.has_rate_issue, false) THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'RATE_ISSUE', 'message', 'Cannot process: TSFIN has a rate issue.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;
  IF COALESCE(v_current_tsfin.has_pay_channel_issue, false) THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'PAY_CHANNEL_ISSUE', 'message', 'Cannot process: TSFIN has a pay channel issue.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_current_tsfin.pay_method, '')), '') IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'PAY_METHOD_MISSING', 'message', 'Cannot process: pay method is missing from TSFIN context.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;
  IF v_current_tsfin.candidate_assignment = 'UNASSIGNED'::public.candidate_assignment_enum THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'CANDIDATE_ASSIGNMENT_UNRESOLVED', 'message', 'Cannot process: candidate assignment is unresolved in TSFIN context.', 'current_timesheet_id', v_current_ts.timesheet_id);
  END IF;

  v_before_signature_json := public.timesheet_lifecycle_signature_v1(v_current_ts.timesheet_id, NULL::uuid, false);
  v_current_row_signature := NULLIF(BTRIM(COALESCE(v_before_signature_json ->> 'backend_row_signature', v_before_signature_json ->> 'row_signature', v_before_signature_json ->> 'signature', '')), '');
  v_expected_row_signature := NULLIF(BTRIM(COALESCE(p_expected_row_signature, v_timesheet_patch ->> 'backend_row_signature', v_timesheet_patch ->> 'row_signature', v_tsfin_patch ->> 'backend_row_signature', v_tsfin_patch ->> 'row_signature', '')), '');

  IF v_expected_row_signature IS NOT NULL AND COALESCE(v_current_row_signature, '') IS DISTINCT FROM v_expected_row_signature THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'ROW_SIGNATURE_MISMATCH', 'message', 'Timesheet changed after it was loaded. Refresh the row and try again.', 'current_timesheet_id', v_current_ts.timesheet_id, 'expected_row_signature', v_expected_row_signature, 'current_row_signature', v_current_row_signature);
  END IF;

  UPDATE public.timesheets AS ts
     SET reference_number = CASE WHEN v_timesheet_patch ? 'reference_number' THEN NULLIF(BTRIM(v_timesheet_patch ->> 'reference_number'), '') ELSE ts.reference_number END,
         reference_set_at = CASE
           WHEN v_timesheet_patch ? 'reference_number' THEN
             CASE WHEN NULLIF(BTRIM(v_timesheet_patch ->> 'reference_number'), '') IS NULL THEN NULL::timestamp with time zone
                  WHEN NULLIF(BTRIM(v_timesheet_patch ->> 'reference_number'), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(ts.reference_number, '')), '') THEN v_now
                  ELSE COALESCE(ts.reference_set_at, v_now)
             END
           ELSE ts.reference_set_at
         END,
         submission_mode = CASE WHEN v_candidate_electronic_context
           THEN 'ELECTRONIC'::public.submission_mode_enum ELSE ts.submission_mode END,
         auth_name = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(BTRIM(v_timesheet_patch->>'auth_name'),'') ELSE ts.auth_name END,
         auth_job_title = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(BTRIM(v_timesheet_patch->>'auth_job_title'),'') ELSE ts.auth_job_title END,
         r2_nurse_key = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(BTRIM(v_timesheet_patch->>'r2_nurse_key'),'') ELSE ts.r2_nurse_key END,
         r2_auth_key = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(BTRIM(v_timesheet_patch->>'r2_auth_key'),'') ELSE ts.r2_auth_key END,
         img_sha256_nurse = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(BTRIM(v_timesheet_patch->>'img_sha256_nurse'),'') ELSE ts.img_sha256_nurse END,
         img_sha256_auth = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(BTRIM(v_timesheet_patch->>'img_sha256_auth'),'') ELSE ts.img_sha256_auth END,
         candidate_workflow_id = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(v_timesheet_patch->>'candidate_workflow_id','')::uuid ELSE ts.candidate_workflow_id END,
         candidate_workflow_generation = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(v_timesheet_patch->>'candidate_workflow_generation','')::integer ELSE ts.candidate_workflow_generation END,
         candidate_manager_approved_at_utc = CASE WHEN v_candidate_electronic_context
           THEN NULLIF(v_timesheet_patch->>'candidate_manager_approved_at_utc','')::timestamptz
           ELSE ts.candidate_manager_approved_at_utc END,
         updated_at = v_now
   WHERE ts.timesheet_id = v_current_ts.timesheet_id
     AND ts.is_current = true
   RETURNING * INTO v_current_ts;

  UPDATE public.timesheets_financials AS tf
     SET processing_status = v_new_status,
         processed_by_user_id = p_actor_user_id,
         processed_at_utc = v_now,
         authorised_by_user_id = NULL,
         authorised_at_utc = NULL,
         updated_at = v_now
   WHERE tf.id = v_current_tsfin.id
     AND tf.is_current = true
   RETURNING * INTO v_current_tsfin;

  v_after_signature_json := public.timesheet_lifecycle_signature_v1(v_current_ts.timesheet_id, NULL::uuid, false);
  v_after_row_signature := NULLIF(BTRIM(COALESCE(v_after_signature_json ->> 'backend_row_signature', v_after_signature_json ->> 'row_signature', v_after_signature_json ->> 'signature', '')), '');

  PERFORM public._audit_insert(
    'timesheet',
    v_current_ts.timesheet_id::text,
    'TIMESHEET_DAILY_MANUAL_PROCESSED',
    jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'previous_processing_status', v_previous_status::text, 'previous_row_signature', v_current_row_signature),
    jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'new_processing_status', v_new_status::text, 'processed_at_utc', v_now, 'processed_by_user_id', p_actor_user_id, 'new_row_signature', v_after_row_signature),
    'DAILY_MANUAL_PROCESS',
    p_actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'success', true,
    'operation', 'daily_manual_process',
    'processed', true,
    'requested_timesheet_id', p_timesheet_id,
    'expected_timesheet_id', p_expected_timesheet_id,
    'current_timesheet_id', v_current_ts.timesheet_id,
    'timesheet_id', v_current_ts.timesheet_id,
    'timesheet_financials_id', v_current_tsfin.id,
    'current_version', v_current_ts.version,
    'was_stale', v_requested_ts.timesheet_id IS DISTINCT FROM v_current_ts.timesheet_id,
    'previous_status', v_previous_status::text,
    'processing_status', v_new_status::text,
    'new_processing_status', v_new_status::text,
    'backend_row_signature', v_after_row_signature,
    'row_signature', v_after_row_signature,
    'status_transition', jsonb_build_object('from', v_previous_status::text, 'to', v_new_status::text, 'processed_at_utc', v_now, 'processed_by_user_id', p_actor_user_id),
    'affected_rows', jsonb_build_array(jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'row_key', 'timesheet:' || v_current_ts.timesheet_id::text)),
    'count_deltas', jsonb_build_object('unprocessed', -1, 'processed', 1),
    'cache_invalidation_hints', jsonb_build_object('changed_domains', jsonb_build_array('timesheets', 'timesheets_financials'), 'timesheet_id', v_current_ts.timesheet_id)
  );
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS v_error_state = RETURNED_SQLSTATE, v_error_message = MESSAGE_TEXT;
  IF v_error_state = '55P03' THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'LOCK_TIMEOUT', 'message', 'The timesheet is currently locked by another operation.', 'timesheet_id', p_timesheet_id);
  END IF;
  RAISE;
END;

exceptions.text:
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS v_error_state = RETURNED_SQLSTATE, v_error_message = MESSAGE_TEXT;
  IF v_error_state = '55P03' THEN
    RETURN jsonb_build_object('ok', false, 'operation', 'daily_manual_process', 'error_code', 'LOCK_TIMEOUT', 'message', 'The timesheet is currently locked by another operation.', 'timesheet_id', p_timesheet_id);
  END IF;
  RAISE;
END;

routines.body:
declare
  v_environment text:=private._candidate_assert_environment(p_environment);
  v_timesheet_ids uuid[];
  v_workflows jsonb:='[]'::jsonb;
  v_cancelable jsonb:='[]'::jsonb;
  v_blocking jsonb:='[]'::jsonb;
  v_context_sha256 text;
  v_item jsonb;
  v_is_cancelable boolean;
  v_integrity_ok boolean;
begin
  select coalesce(array_agg(distinct supplied_id order by supplied_id),array[]::uuid[])
  into v_timesheet_ids
  from unnest(coalesce(p_timesheet_ids,array[]::uuid[])) supplied(supplied_id)
  where supplied_id is not null;

  if cardinality(v_timesheet_ids)<1 or cardinality(v_timesheet_ids)>64 then
    raise exception 'PENDING_EXPENSE_DELETE_TARGET_SET_INVALID' using errcode='22023';
  end if;

  if p_lock_workflows then
    perform 1
    from public.candidate_submission_workflows workflow_row
    join public.timesheets anchor_timesheet
      on anchor_timesheet.timesheet_id=workflow_row.anchor_timesheet_id
    where workflow_row.environment=v_environment
      and workflow_row.workflow_kind='CONTRACT_EXPENSE'
      and workflow_row.target_timesheet_id is null
      and workflow_row.state not in ('FINALISED','CANCELLED','REJECTED','EXPIRED','SUPERSEDED')
      and exists(
        select 1
        from public.timesheets delete_timesheet
        where delete_timesheet.timesheet_id=any(v_timesheet_ids)
          and (
            delete_timesheet.timesheet_id=anchor_timesheet.timesheet_id
            or (
              delete_timesheet.booking_id is not distinct from anchor_timesheet.booking_id
              and delete_timesheet.occupant_key_norm=anchor_timesheet.occupant_key_norm
              and delete_timesheet.contract_id is not distinct from anchor_timesheet.contract_id
              and delete_timesheet.week_ending_date is not distinct from anchor_timesheet.week_ending_date
            )
          )
      )
    order by workflow_row.id
    for update of workflow_row;
  end if;

  for v_item in
    select jsonb_build_object(
      'workflow_id',workflow_row.id,
      'generation',workflow_row.generation,
      'state',workflow_row.state,
      'route',workflow_row.route,
      'anchor_timesheet_id',workflow_row.anchor_timesheet_id,
      'contract_week_id',workflow_row.contract_week_id,
      'carrier_timesheet_id',carrier_week.timesheet_id,
      'integrity_ok',(
        carrier_week.id is not null
        and carrier_week.timesheet_id is null
        and carrier_week.contract_id is not distinct from workflow_row.contract_id
        and carrier_week.week_ending_date is not distinct from workflow_row.week_ending_date
        and anchor_timesheet.contract_id is not distinct from workflow_row.contract_id
        and anchor_timesheet.week_ending_date is not distinct from workflow_row.week_ending_date
      ),
      'approval_requests',coalesce((
        select jsonb_agg(jsonb_build_object(
          'approval_request_id',approval.id,
          'workflow_generation',approval.workflow_generation,
          'request_generation',approval.request_generation,
          'method',approval.method,
          'state',approval.state
        ) order by approval.id)
        from public.candidate_approval_requests approval
        where approval.workflow_id=workflow_row.id
          and approval.state in ('PENDING','APPROVED')
      ),'[]'::jsonb)
    )
    from public.candidate_submission_workflows workflow_row
    join public.timesheets anchor_timesheet
      on anchor_timesheet.timesheet_id=workflow_row.anchor_timesheet_id
    left join public.contract_weeks carrier_week
      on carrier_week.id=workflow_row.contract_week_id
    where workflow_row.environment=v_environment
      and workflow_row.workflow_kind='CONTRACT_EXPENSE'
      and workflow_row.target_timesheet_id is null
      and workflow_row.state not in ('FINALISED','CANCELLED','REJECTED','EXPIRED','SUPERSEDED')
      and exists(
        select 1
        from public.timesheets delete_timesheet
        where delete_timesheet.timesheet_id=any(v_timesheet_ids)
          and (
            delete_timesheet.timesheet_id=anchor_timesheet.timesheet_id
            or (
              delete_timesheet.booking_id is not distinct from anchor_timesheet.booking_id
              and delete_timesheet.occupant_key_norm=anchor_timesheet.occupant_key_norm
              and delete_timesheet.contract_id is not distinct from anchor_timesheet.contract_id
              and delete_timesheet.week_ending_date is not distinct from anchor_timesheet.week_ending_date
            )
          )
      )
    order by workflow_row.id
  loop
    v_workflows:=v_workflows||jsonb_build_array(v_item);
    v_integrity_ok:=coalesce((v_item->>'integrity_ok')::boolean,false);
    v_is_cancelable:=v_integrity_ok and (v_item->>'state') in (
      'CREATED','WORKER_DRAFT','WORKER_SUBMITTED',
      'WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT','READY_FOR_MANAGER_APPROVAL',
      'AWAITING_MANAGER_APPROVAL','AWAITING_PAPER_RETURN','REFUSED'
    ) and not exists(
      select 1
      from jsonb_array_elements(coalesce(v_item->'approval_requests','[]'::jsonb)) approval(item)
      where approval.item->>'state'='APPROVED'
    );
    if v_is_cancelable then
      v_cancelable:=v_cancelable||jsonb_build_array(v_item);
    else
      v_blocking:=v_blocking||jsonb_build_array(v_item||jsonb_build_object(
        'blocker_code',case
          when not v_integrity_ok then 'PENDING_EXPENSE_CARRIER_INCONSISTENT'
          when exists(
            select 1
            from jsonb_array_elements(coalesce(v_item->'approval_requests','[]'::jsonb)) approval(item)
            where approval.item->>'state'='APPROVED'
          ) then 'PENDING_EXPENSE_MANAGER_APPROVAL_ALREADY_RECORDED'
          else 'PENDING_EXPENSE_MANAGER_APPROVAL_ALREADY_RECORDED'
        end
      ));
    end if;
  end loop;

  if jsonb_array_length(v_workflows)>20 then
    raise exception 'PENDING_EXPENSE_DELETE_CONTEXT_TOO_LARGE' using errcode='54000';
  end if;

  v_context_sha256:=encode(extensions.digest(convert_to(jsonb_build_object(
    'contract_version','TIMESHEET_PENDING_EXPENSE_DELETE_CONTEXT_V1',
    'environment',v_environment,
    'timesheet_ids',to_jsonb(v_timesheet_ids),
    'workflows',v_workflows
  )::text,'UTF8'),'sha256'),'hex');

  return jsonb_build_object(
    'ok',true,
    'contract_version','TIMESHEET_PENDING_EXPENSE_DELETE_CONTEXT_V1',
    'environment',v_environment,
    'timesheet_ids',to_jsonb(v_timesheet_ids),
    'context_sha256',v_context_sha256,
    'pending_expense_claim_count',jsonb_array_length(v_cancelable),
    'pending_expense_claims',v_cancelable,
    'blocking_claim_count',jsonb_array_length(v_blocking),
    'blocking_claims',v_blocking,
    'cancellation_required',jsonb_array_length(v_cancelable)>0,
    'delete_blocked',jsonb_array_length(v_blocking)>0
  );
end;

routines.definition:
create or replace function public.timesheet_delete_with_pending_expense_apply_v1(
  p_environment text,
  p_delete_kind text,
  p_timesheet_id uuid,
  p_actor_user_id uuid,
  p_expected_timesheet_id uuid,
  p_expected_row_signature text,
  p_expected_timesheet_ids uuid[],
  p_expected_contract_week_ids uuid[],
  p_expected_nhsp_shift_ids uuid[],
  p_expected_preserved_source_timesheet_ids uuid[],
  p_expected_preserved_source_contract_week_ids uuid[],
  p_expected_pending_expense_context_sha256 text,
  p_delete_operation_id uuid,
  p_now_utc timestamptz default now()
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_environment text:=private._candidate_assert_environment(p_environment);
  v_kind text:=upper(btrim(coalesce(p_delete_kind,'')));
  v_context jsonb;
  v_claim jsonb;
  v_workflow public.candidate_submission_workflows%rowtype;
  v_cancel_result jsonb;
  v_cancel_results jsonb:='[]'::jsonb;
  v_notification_id uuid;
  v_notification_ids uuid[]:=array[]::uuid[];
  v_settings jsonb;
  v_template jsonb;
  v_terminal_mail jsonb;
  v_apply_result jsonb;
  v_delete_candidate_ids uuid[]:=array[]::uuid[];
  v_delete_candidate_id uuid;
  v_candidate_lock_key bigint;
  v_banking_dirty_result jsonb:='{}'::jsonb;
begin
  if p_actor_user_id is null or p_timesheet_id is null or p_expected_timesheet_id is null
     or p_delete_operation_id is null or nullif(btrim(coalesce(p_expected_row_signature,'')),'') is null
     or coalesce(p_expected_pending_expense_context_sha256,'') !~ '^[0-9a-f]{64}$'
     or v_kind not in (
       'STANDARD_DELETE','DAILY_ABANDONED_RECEIPT_DELETE',
       'WEEKLY_CHAIN_DELETE_PARENT','WEEKLY_MANUAL_ADJUSTMENT_DELETE'
     ) then
    raise exception 'PENDING_EXPENSE_DELETE_APPLY_INVALID' using errcode='22023';
  end if;

  perform 1
  from public.timesheets delete_timesheet
  where delete_timesheet.timesheet_id=any(p_expected_timesheet_ids)
  order by delete_timesheet.timesheet_id
  for update;

  v_context:=private._timesheet_pending_expense_delete_context_v1(
    v_environment,p_expected_timesheet_ids,true
  );
  if lower(v_context->>'context_sha256') is distinct from
       lower(p_expected_pending_expense_context_sha256) then
    raise exception 'PENDING_EXPENSE_DELETE_CONTEXT_CHANGED'
      using errcode='40001',detail=v_context::text;
  end if;
  if coalesce((v_context->>'delete_blocked')::boolean,false) then
    raise exception 'PENDING_EXPENSE_DELETE_BLOCKED'
      using errcode='55000',detail=v_context::text;
  end if;

  -- Every supported removal unit belongs to one Candidate. Capture and lock
  -- that owner while the Timesheets still exist so deletion cannot leave a
  -- stale Banking Pay view or try to validate a Timesheet after it is gone.
  select coalesce(array_agg(distinct owner.candidate_id order by owner.candidate_id),array[]::uuid[])
  into v_delete_candidate_ids
  from (
    select contract_row.candidate_id
    from public.timesheets timesheet_row
    join public.contracts contract_row on contract_row.id=timesheet_row.contract_id
    where timesheet_row.timesheet_id=any(p_expected_timesheet_ids)
    union all
    select financial_row.candidate_id
    from public.timesheets_financials financial_row
    where financial_row.timesheet_id=any(p_expected_timesheet_ids)
      and financial_row.is_current
    union all
    select request.candidate_id from private.timesheet_correction_requests request
    where request.replacement_timesheet_id=any(p_expected_timesheet_ids)
      and private.timesheet_correction_cancel_capability_v1(request.replacement_timesheet_id,p_actor_user_id) is not null
  ) owner
  where owner.candidate_id is not null;
  if cardinality(v_delete_candidate_ids)<>1 then
    raise exception 'TIMESHEET_DELETE_CANDIDATE_OWNERSHIP_INVALID'
      using errcode='23514',detail=jsonb_build_object(
        'candidate_count',cardinality(v_delete_candidate_ids)
      )::text;
  end if;
  v_delete_candidate_id:=v_delete_candidate_ids[1];
  v_candidate_lock_key:=pg_catalog.hashtextextended(
    public._pay_workbench_candidate_serial_key(v_delete_candidate_id),24062027
  );
  perform pg_catalog.pg_advisory_xact_lock(v_candidate_lock_key);

  if coalesce((v_context->>'cancellation_required')::boolean,false) then
    v_settings:=public.candidate_manager_email_settings_get_v1();
    v_template:=v_settings#>'{templates,EXPENSE_CLAIM,CANCELLATION}';
    v_terminal_mail:=jsonb_build_object(
      'subject',v_template->>'subject',
      'body_text',v_template->>'body_text',
      'body_html',v_template->>'body_html',
      'manager_template_version',v_settings->'version',
      'manager_template_sha256',v_settings->>'semantic_sha256_hex',
      'manager_submission_type','EXPENSE_CLAIM'
    );
  end if;

  for v_claim in
    select value from jsonb_array_elements(coalesce(
      v_context->'pending_expense_claims','[]'::jsonb
    )) items(value)
  loop
    select workflow_row.* into strict v_workflow
    from public.candidate_submission_workflows workflow_row
    where workflow_row.id=(v_claim->>'workflow_id')::uuid
      and workflow_row.generation=(v_claim->>'generation')::integer
      and workflow_row.environment=v_environment
      and workflow_row.workflow_kind='CONTRACT_EXPENSE'
      and workflow_row.target_timesheet_id is null
    for update;

    perform 1 from public.candidate_notifications notification
    where notification.workflow_id=v_workflow.id
       or notification.timesheet_id=any(p_expected_timesheet_ids)
    order by notification.id
    for update;

    perform private._candidate_office_service_context_open_v1(
      v_environment,p_actor_user_id,'delete_timesheet','CANCEL',p_now_utc
    );
    v_cancel_result:=public.candidate_workflow_cancel_atomic_v2(
      null,v_environment,v_workflow.id,v_workflow.generation,
      jsonb_build_object(
        'service_office_action',true,
        'actor_user_id',p_actor_user_id,
        'reason_note','Pending expense claim cancelled because its Timesheet was deleted.',
        'reason_code','TIMESHEET_DELETED',
        'manager_terminal_mail',v_terminal_mail
      ),
      'office-timesheet-delete:'||p_delete_operation_id::text||':'||v_workflow.id::text,
      p_now_utc
    );
    perform private._candidate_office_service_context_close_v1();

    update public.candidate_submission_components component
    set timesheet_id=null
    where component.workflow_id=v_workflow.id
      and component.timesheet_id=any(p_expected_timesheet_ids);

    update public.candidate_notifications notification
    set timesheet_id=null,
        deep_link_json=(coalesce(notification.deep_link_json,'{}'::jsonb)
          -'timesheet_id'-'contract_week_id')||jsonb_build_object(
            'type','workflow','workflow_id',v_workflow.id
          ),
        state='DISMISSED',
        dismissed_at_utc=coalesce(notification.dismissed_at_utc,p_now_utc),
        push_state=case
          when notification.push_state in ('PENDING','FAILED','CLAIMED') then 'SKIPPED'
          else notification.push_state
        end
    where notification.workflow_id=v_workflow.id;

    update public.candidate_submission_workflows workflow_row
    set contract_week_id=null,
        anchor_timesheet_id=null,
        target_timesheet_id=null,
        input_snapshot_json=coalesce(workflow_row.input_snapshot_json,'{}'::jsonb)
          ||jsonb_build_object(
            'office_permanent_delete_tombstone',jsonb_build_object(
              'delete_operation_id',p_delete_operation_id,
              'deleted_timesheet_ids',to_jsonb(p_expected_timesheet_ids),
              'deleted_contract_week_ids',to_jsonb(p_expected_contract_week_ids),
              'previous_contract_week_id',v_workflow.contract_week_id,
              'previous_anchor_timesheet_id',v_workflow.anchor_timesheet_id,
              'previous_target_timesheet_id',v_workflow.target_timesheet_id,
              'retired_at_utc',p_now_utc
            )
          ),
        issue_codes=(case
          when workflow_row.issue_codes @> '["OFFICE_TIMESHEET_DELETED_EXPENSE_CANCELLED"]'::jsonb
            then workflow_row.issue_codes
          else workflow_row.issue_codes||'["OFFICE_TIMESHEET_DELETED_EXPENSE_CANCELLED"]'::jsonb
        end)||(case
          when workflow_row.issue_codes @> '["OFFICE_PERMANENTLY_DELETED_TIMESHEET"]'::jsonb
            then '[]'::jsonb
          else '["OFFICE_PERMANENTLY_DELETED_TIMESHEET"]'::jsonb
        end),
        updated_at_utc=p_now_utc
    where workflow_row.id=v_workflow.id
      and workflow_row.state='CANCELLED'
      and workflow_row.target_timesheet_id is null;
    if not found then
      raise exception 'PENDING_EXPENSE_CANCELLATION_NOT_PROVEN' using errcode='40001';
    end if;

    insert into public.candidate_notifications(
      account_id,candidate_id,workflow_id,timesheet_id,event_type,preference_category,
      template_key,template_params,deep_link_json,state,push_state,dedupe_key,created_at_utc
    )
    select
      v_workflow.account_id,v_workflow.candidate_id,v_workflow.id,null,
      'EXPENSE_CLAIM_CANCELLED','timesheet_expense_attention',
      'candidate-expense-claim-cancelled-timesheet-delete-v1',
      jsonb_build_object(
        'workflow_id',v_workflow.id,
        'reason_code','TIMESHEET_DELETED'
      ),
      jsonb_build_object('type','workflow','workflow_id',v_workflow.id),
      'UNREAD',
      case
        when account.status='ACTIVE'
          and coalesce((account.notification_preferences_json->>'push')::boolean,true)
          and coalesce(
            (account.notification_preferences_json->>'timesheet_expense_attention')::boolean,
            (account.notification_preferences_json->>'office_rejection')::boolean,
            true
          )
          then 'PENDING'
        else 'SKIPPED'
      end,
      'CANDIDATE_EXPENSE_CLAIM_CANCELLED_TIMESHEET_DELETE_V1:'
        ||v_workflow.id::text||':'||v_workflow.generation::text,
      p_now_utc
    from public.candidate_app_accounts account
    where account.id=v_workflow.account_id
    on conflict(dedupe_key) do update set dedupe_key=excluded.dedupe_key
    returning id into v_notification_id;

    v_notification_ids:=array_append(v_notification_ids,v_notification_id);
    v_cancel_results:=v_cancel_results||jsonb_build_array(jsonb_build_object(
      'workflow_id',v_workflow.id,
      'previous_generation',v_workflow.generation,
      'state','CANCELLED',
      'notification_id',v_notification_id,
      'cancellation',v_cancel_result
    ));
  end loop;

  -- The established Timesheet delete removes financial rows before the
  -- Timesheet. Suppress only the duplicate row-level delete signals for this
  -- one locked Candidate, then issue one complete Candidate refresh after the
  -- authoritative delete has been proved. This uses the existing sealed
  -- Banking Pay suppression boundary and changes no financial truth.
  if pg_catalog.to_regclass('pg_temp._bpay_candidate_delete_context_v1') is not null then
    raise exception 'PAY_WORKBENCH_CANDIDATE_DELETE_CONTEXT_CONFLICT' using errcode='23514';
  end if;
  create temp table pg_temp._bpay_candidate_delete_context_v1(
    candidate_id uuid primary key,
    delete_operation_id uuid unique not null,
    candidate_lock_key bigint not null,
    backend_pid integer not null,
    transaction_id bigint not null,
    created_at_utc timestamptz not null,
    suppress boolean not null check(suppress)
  ) on commit drop;
  insert into pg_temp._bpay_candidate_delete_context_v1 values(
    v_delete_candidate_id,p_delete_operation_id,v_candidate_lock_key,
    pg_catalog.pg_backend_pid(),pg_catalog.txid_current(),p_now_utc,true
  );

  if v_kind='STANDARD_DELETE' then
    v_apply_result:=public.timesheet_standard_delete_apply_v1(
      p_timesheet_id,p_actor_user_id,p_expected_timesheet_id,p_expected_row_signature
    );
  elsif v_kind='DAILY_ABANDONED_RECEIPT_DELETE' then
    v_apply_result:=public.timesheet_daily_abandoned_receipt_delete_apply_v1(
      p_timesheet_id,p_actor_user_id,p_expected_timesheet_id,p_expected_row_signature
    );
  elsif v_kind='WEEKLY_CHAIN_DELETE_PARENT' then
    v_apply_result:=public.timesheet_weekly_chain_delete_apply(
      p_timesheet_id,p_actor_user_id,p_expected_timesheet_ids,
      p_expected_contract_week_ids,p_expected_nhsp_shift_ids,p_expected_row_signature
    );
  else
    v_apply_result:=public.timesheet_weekly_manual_adjustment_delete_apply(
      p_timesheet_id,p_actor_user_id,p_expected_timesheet_ids,
      p_expected_contract_week_ids,p_expected_preserved_source_timesheet_ids,
      p_expected_preserved_source_contract_week_ids,p_expected_row_signature
    );
  end if;

  if coalesce((v_apply_result->>'apply_performed')::boolean,false) is not true
     or upper(coalesce(v_apply_result->>'decision',''))<>'PERMANENT_DELETE' then
    raise exception 'TIMESHEET_DELETE_AFTER_EXPENSE_CANCELLATION_NOT_PROVEN'
      using errcode='40001',detail=coalesce(v_apply_result,'{}'::jsonb)::text;
  end if;

  drop table pg_temp._bpay_candidate_delete_context_v1;
  v_banking_dirty_result:=public.pay_workbench_dirty_event_enqueue(
    p_job_type=>'WORKBENCH_CANDIDATE_DIRTY_APPLY',
    p_scope_kind=>'CANDIDATE',
    p_scope_id=>v_delete_candidate_id::text,
    p_candidate_id=>v_delete_candidate_id,
    p_targeted_timesheet_ids=>array[]::uuid[],
    p_linked_timesheet_ids=>array[]::uuid[],
    p_payload_json=>jsonb_build_object(
      'trigger_table','timesheets',
      'trigger_op','DELETE',
      'trigger_operation','DELETE',
      'delete_operation_id',p_delete_operation_id,
      'deleted_timesheet_ids',coalesce(v_apply_result->'deleted_timesheet_ids','[]'::jsonb),
      'scope_resolution','CANDIDATE_FULL_AFTER_TIMESHEET_DELETE',
      'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH',
      'economic_truth_mutation_allowed',false
    ),
    p_reason=>'DIRTY_TRIGGER:TIMESHEETS:DELETE',
    p_priority=>-1000,
    p_run_at_utc=>p_now_utc
  );
  if coalesce((v_banking_dirty_result->>'ok')::boolean,false) is not true then
    raise exception 'TIMESHEET_DELETE_BANKING_REFRESH_NOT_PROVEN'
      using errcode='40001',detail=coalesce(v_banking_dirty_result,'{}'::jsonb)::text;
  end if;

  return v_apply_result||jsonb_build_object(
    'pending_expense_context_sha256',v_context->>'context_sha256',
    'cancelled_pending_expense_claim_count',jsonb_array_length(v_cancel_results),
    'cancelled_pending_expense_claims',v_cancel_results,
    'candidate_notification_ids',to_jsonb(v_notification_ids),
    'banking_pay_candidate_refresh',v_banking_dirty_result
  );
exception when others then
  perform private._candidate_office_service_context_close_v1();
  raise;
end;
$function$;

routines.body:
declare
  v_environment text:=private._candidate_assert_environment(p_environment);
  v_kind text:=upper(btrim(coalesce(p_delete_kind,'')));
  v_context jsonb;
  v_claim jsonb;
  v_workflow public.candidate_submission_workflows%rowtype;
  v_cancel_result jsonb;
  v_cancel_results jsonb:='[]'::jsonb;
  v_notification_id uuid;
  v_notification_ids uuid[]:=array[]::uuid[];
  v_settings jsonb;
  v_template jsonb;
  v_terminal_mail jsonb;
  v_apply_result jsonb;
  v_delete_candidate_ids uuid[]:=array[]::uuid[];
  v_delete_candidate_id uuid;
  v_candidate_lock_key bigint;
  v_banking_dirty_result jsonb:='{}'::jsonb;
begin
  if p_actor_user_id is null or p_timesheet_id is null or p_expected_timesheet_id is null
     or p_delete_operation_id is null or nullif(btrim(coalesce(p_expected_row_signature,'')),'') is null
     or coalesce(p_expected_pending_expense_context_sha256,'') !~ '^[0-9a-f]{64}$'
     or v_kind not in (
       'STANDARD_DELETE','DAILY_ABANDONED_RECEIPT_DELETE',
       'WEEKLY_CHAIN_DELETE_PARENT','WEEKLY_MANUAL_ADJUSTMENT_DELETE'
     ) then
    raise exception 'PENDING_EXPENSE_DELETE_APPLY_INVALID' using errcode='22023';
  end if;

  perform 1
  from public.timesheets delete_timesheet
  where delete_timesheet.timesheet_id=any(p_expected_timesheet_ids)
  order by delete_timesheet.timesheet_id
  for update;

  v_context:=private._timesheet_pending_expense_delete_context_v1(
    v_environment,p_expected_timesheet_ids,true
  );
  if lower(v_context->>'context_sha256') is distinct from
       lower(p_expected_pending_expense_context_sha256) then
    raise exception 'PENDING_EXPENSE_DELETE_CONTEXT_CHANGED'
      using errcode='40001',detail=v_context::text;
  end if;
  if coalesce((v_context->>'delete_blocked')::boolean,false) then
    raise exception 'PENDING_EXPENSE_DELETE_BLOCKED'
      using errcode='55000',detail=v_context::text;
  end if;

  -- Every supported removal unit belongs to one Candidate. Capture and lock
  -- that owner while the Timesheets still exist so deletion cannot leave a
  -- stale Banking Pay view or try to validate a Timesheet after it is gone.
  select coalesce(array_agg(distinct owner.candidate_id order by owner.candidate_id),array[]::uuid[])
  into v_delete_candidate_ids
  from (
    select contract_row.candidate_id
    from public.timesheets timesheet_row
    join public.contracts contract_row on contract_row.id=timesheet_row.contract_id
    where timesheet_row.timesheet_id=any(p_expected_timesheet_ids)
    union all
    select financial_row.candidate_id
    from public.timesheets_financials financial_row
    where financial_row.timesheet_id=any(p_expected_timesheet_ids)
      and financial_row.is_current
    union all
    select request.candidate_id from private.timesheet_correction_requests request
    where request.replacement_timesheet_id=any(p_expected_timesheet_ids)
      and private.timesheet_correction_cancel_capability_v1(request.replacement_timesheet_id,p_actor_user_id) is not null
  ) owner
  where owner.candidate_id is not null;
  if cardinality(v_delete_candidate_ids)<>1 then
    raise exception 'TIMESHEET_DELETE_CANDIDATE_OWNERSHIP_INVALID'
      using errcode='23514',detail=jsonb_build_object(
        'candidate_count',cardinality(v_delete_candidate_ids)
      )::text;
  end if;
  v_delete_candidate_id:=v_delete_candidate_ids[1];
  v_candidate_lock_key:=pg_catalog.hashtextextended(
    public._pay_workbench_candidate_serial_key(v_delete_candidate_id),24062027
  );
  perform pg_catalog.pg_advisory_xact_lock(v_candidate_lock_key);

  if coalesce((v_context->>'cancellation_required')::boolean,false) then
    v_settings:=public.candidate_manager_email_settings_get_v1();
    v_template:=v_settings#>'{templates,EXPENSE_CLAIM,CANCELLATION}';
    v_terminal_mail:=jsonb_build_object(
      'subject',v_template->>'subject',
      'body_text',v_template->>'body_text',
      'body_html',v_template->>'body_html',
      'manager_template_version',v_settings->'version',
      'manager_template_sha256',v_settings->>'semantic_sha256_hex',
      'manager_submission_type','EXPENSE_CLAIM'
    );
  end if;

  for v_claim in
    select value from jsonb_array_elements(coalesce(
      v_context->'pending_expense_claims','[]'::jsonb
    )) items(value)
  loop
    select workflow_row.* into strict v_workflow
    from public.candidate_submission_workflows workflow_row
    where workflow_row.id=(v_claim->>'workflow_id')::uuid
      and workflow_row.generation=(v_claim->>'generation')::integer
      and workflow_row.environment=v_environment
      and workflow_row.workflow_kind='CONTRACT_EXPENSE'
      and workflow_row.target_timesheet_id is null
    for update;

    perform 1 from public.candidate_notifications notification
    where notification.workflow_id=v_workflow.id
       or notification.timesheet_id=any(p_expected_timesheet_ids)
    order by notification.id
    for update;

    perform private._candidate_office_service_context_open_v1(
      v_environment,p_actor_user_id,'delete_timesheet','CANCEL',p_now_utc
    );
    v_cancel_result:=public.candidate_workflow_cancel_atomic_v2(
      null,v_environment,v_workflow.id,v_workflow.generation,
      jsonb_build_object(
        'service_office_action',true,
        'actor_user_id',p_actor_user_id,
        'reason_note','Pending expense claim cancelled because its Timesheet was deleted.',
        'reason_code','TIMESHEET_DELETED',
        'manager_terminal_mail',v_terminal_mail
      ),
      'office-timesheet-delete:'||p_delete_operation_id::text||':'||v_workflow.id::text,
      p_now_utc
    );
    perform private._candidate_office_service_context_close_v1();

    update public.candidate_submission_components component
    set timesheet_id=null
    where component.workflow_id=v_workflow.id
      and component.timesheet_id=any(p_expected_timesheet_ids);

    update public.candidate_notifications notification
    set timesheet_id=null,
        deep_link_json=(coalesce(notification.deep_link_json,'{}'::jsonb)
          -'timesheet_id'-'contract_week_id')||jsonb_build_object(
            'type','workflow','workflow_id',v_workflow.id
          ),
        state='DISMISSED',
        dismissed_at_utc=coalesce(notification.dismissed_at_utc,p_now_utc),
        push_state=case
          when notification.push_state in ('PENDING','FAILED','CLAIMED') then 'SKIPPED'
          else notification.push_state
        end
    where notification.workflow_id=v_workflow.id;

    update public.candidate_submission_workflows workflow_row
    set contract_week_id=null,
        anchor_timesheet_id=null,
        target_timesheet_id=null,
        input_snapshot_json=coalesce(workflow_row.input_snapshot_json,'{}'::jsonb)
          ||jsonb_build_object(
            'office_permanent_delete_tombstone',jsonb_build_object(
              'delete_operation_id',p_delete_operation_id,
              'deleted_timesheet_ids',to_jsonb(p_expected_timesheet_ids),
              'deleted_contract_week_ids',to_jsonb(p_expected_contract_week_ids),
              'previous_contract_week_id',v_workflow.contract_week_id,
              'previous_anchor_timesheet_id',v_workflow.anchor_timesheet_id,
              'previous_target_timesheet_id',v_workflow.target_timesheet_id,
              'retired_at_utc',p_now_utc
            )
          ),
        issue_codes=(case
          when workflow_row.issue_codes @> '["OFFICE_TIMESHEET_DELETED_EXPENSE_CANCELLED"]'::jsonb
            then workflow_row.issue_codes
          else workflow_row.issue_codes||'["OFFICE_TIMESHEET_DELETED_EXPENSE_CANCELLED"]'::jsonb
        end)||(case
          when workflow_row.issue_codes @> '["OFFICE_PERMANENTLY_DELETED_TIMESHEET"]'::jsonb
            then '[]'::jsonb
          else '["OFFICE_PERMANENTLY_DELETED_TIMESHEET"]'::jsonb
        end),
        updated_at_utc=p_now_utc
    where workflow_row.id=v_workflow.id
      and workflow_row.state='CANCELLED'
      and workflow_row.target_timesheet_id is null;
    if not found then
      raise exception 'PENDING_EXPENSE_CANCELLATION_NOT_PROVEN' using errcode='40001';
    end if;

    insert into public.candidate_notifications(
      account_id,candidate_id,workflow_id,timesheet_id,event_type,preference_category,
      template_key,template_params,deep_link_json,state,push_state,dedupe_key,created_at_utc
    )
    select
      v_workflow.account_id,v_workflow.candidate_id,v_workflow.id,null,
      'EXPENSE_CLAIM_CANCELLED','timesheet_expense_attention',
      'candidate-expense-claim-cancelled-timesheet-delete-v1',
      jsonb_build_object(
        'workflow_id',v_workflow.id,
        'reason_code','TIMESHEET_DELETED'
      ),
      jsonb_build_object('type','workflow','workflow_id',v_workflow.id),
      'UNREAD',
      case
        when account.status='ACTIVE'
          and coalesce((account.notification_preferences_json->>'push')::boolean,true)
          and coalesce(
            (account.notification_preferences_json->>'timesheet_expense_attention')::boolean,
            (account.notification_preferences_json->>'office_rejection')::boolean,
            true
          )
          then 'PENDING'
        else 'SKIPPED'
      end,
      'CANDIDATE_EXPENSE_CLAIM_CANCELLED_TIMESHEET_DELETE_V1:'
        ||v_workflow.id::text||':'||v_workflow.generation::text,
      p_now_utc
    from public.candidate_app_accounts account
    where account.id=v_workflow.account_id
    on conflict(dedupe_key) do update set dedupe_key=excluded.dedupe_key
    returning id into v_notification_id;

    v_notification_ids:=array_append(v_notification_ids,v_notification_id);
    v_cancel_results:=v_cancel_results||jsonb_build_array(jsonb_build_object(
      'workflow_id',v_workflow.id,
      'previous_generation',v_workflow.generation,
      'state','CANCELLED',
      'notification_id',v_notification_id,
      'cancellation',v_cancel_result
    ));
  end loop;

  -- The established Timesheet delete removes financial rows before the
  -- Timesheet. Suppress only the duplicate row-level delete signals for this
  -- one locked Candidate, then issue one complete Candidate refresh after the
  -- authoritative delete has been proved. This uses the existing sealed
  -- Banking Pay suppression boundary and changes no financial truth.
  if pg_catalog.to_regclass('pg_temp._bpay_candidate_delete_context_v1') is not null then
    raise exception 'PAY_WORKBENCH_CANDIDATE_DELETE_CONTEXT_CONFLICT' using errcode='23514';
  end if;
  create temp table pg_temp._bpay_candidate_delete_context_v1(
    candidate_id uuid primary key,
    delete_operation_id uuid unique not null,
    candidate_lock_key bigint not null,
    backend_pid integer not null,
    transaction_id bigint not null,
    created_at_utc timestamptz not null,
    suppress boolean not null check(suppress)
  ) on commit drop;
  insert into pg_temp._bpay_candidate_delete_context_v1 values(
    v_delete_candidate_id,p_delete_operation_id,v_candidate_lock_key,
    pg_catalog.pg_backend_pid(),pg_catalog.txid_current(),p_now_utc,true
  );

  if v_kind='STANDARD_DELETE' then
    v_apply_result:=public.timesheet_standard_delete_apply_v1(
      p_timesheet_id,p_actor_user_id,p_expected_timesheet_id,p_expected_row_signature
    );
  elsif v_kind='DAILY_ABANDONED_RECEIPT_DELETE' then
    v_apply_result:=public.timesheet_daily_abandoned_receipt_delete_apply_v1(
      p_timesheet_id,p_actor_user_id,p_expected_timesheet_id,p_expected_row_signature
    );
  elsif v_kind='WEEKLY_CHAIN_DELETE_PARENT' then
    v_apply_result:=public.timesheet_weekly_chain_delete_apply(
      p_timesheet_id,p_actor_user_id,p_expected_timesheet_ids,
      p_expected_contract_week_ids,p_expected_nhsp_shift_ids,p_expected_row_signature
    );
  else
    v_apply_result:=public.timesheet_weekly_manual_adjustment_delete_apply(
      p_timesheet_id,p_actor_user_id,p_expected_timesheet_ids,
      p_expected_contract_week_ids,p_expected_preserved_source_timesheet_ids,
      p_expected_preserved_source_contract_week_ids,p_expected_row_signature
    );
  end if;

  if coalesce((v_apply_result->>'apply_performed')::boolean,false) is not true
     or upper(coalesce(v_apply_result->>'decision',''))<>'PERMANENT_DELETE' then
    raise exception 'TIMESHEET_DELETE_AFTER_EXPENSE_CANCELLATION_NOT_PROVEN'
      using errcode='40001',detail=coalesce(v_apply_result,'{}'::jsonb)::text;
  end if;

  drop table pg_temp._bpay_candidate_delete_context_v1;
  v_banking_dirty_result:=public.pay_workbench_dirty_event_enqueue(
    p_job_type=>'WORKBENCH_CANDIDATE_DIRTY_APPLY',
    p_scope_kind=>'CANDIDATE',
    p_scope_id=>v_delete_candidate_id::text,
    p_candidate_id=>v_delete_candidate_id,
    p_targeted_timesheet_ids=>array[]::uuid[],
    p_linked_timesheet_ids=>array[]::uuid[],
    p_payload_json=>jsonb_build_object(
      'trigger_table','timesheets',
      'trigger_op','DELETE',
      'trigger_operation','DELETE',
      'delete_operation_id',p_delete_operation_id,
      'deleted_timesheet_ids',coalesce(v_apply_result->'deleted_timesheet_ids','[]'::jsonb),
      'scope_resolution','CANDIDATE_FULL_AFTER_TIMESHEET_DELETE',
      'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH',
      'economic_truth_mutation_allowed',false
    ),
    p_reason=>'DIRTY_TRIGGER:TIMESHEETS:DELETE',
    p_priority=>-1000,
    p_run_at_utc=>p_now_utc
  );
  if coalesce((v_banking_dirty_result->>'ok')::boolean,false) is not true then
    raise exception 'TIMESHEET_DELETE_BANKING_REFRESH_NOT_PROVEN'
      using errcode='40001',detail=coalesce(v_banking_dirty_result,'{}'::jsonb)::text;
  end if;

  return v_apply_result||jsonb_build_object(
    'pending_expense_context_sha256',v_context->>'context_sha256',
    'cancelled_pending_expense_claim_count',jsonb_array_length(v_cancel_results),
    'cancelled_pending_expense_claims',v_cancel_results,
    'candidate_notification_ids',to_jsonb(v_notification_ids),
    'banking_pay_candidate_refresh',v_banking_dirty_result
  );
exception when others then
  perform private._candidate_office_service_context_close_v1();
  raise;
end;

exceptions.text:
exception when others then
  perform private._candidate_office_service_context_close_v1();
  raise;
end;

