create or replace function private.weekly_source_query_require_service_v1()
returns void
language plpgsql
stable
security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
begin
  if coalesce(
       pg_catalog.current_setting('request.jwt.claim.role',true),
