    -- The actual Contract has one genuinely shared Additional pay field.
    paye_rate:=v_pay; umbrella_rate:=v_pay; charge_rate:=v_charge;
    return next;
  end loop;

  if p_mileage_pay_rate<0 or p_mileage_charge_rate<0
