  p_timesheet_id uuid,p_contract_week_id uuid,p_workflow_kind text
) returns jsonb language plpgsql stable security definer
set search_path = pg_catalog,public,private,pg_temp
as $function$
declare
  v_route jsonb;
  v_policy jsonb;
  v_client_id uuid;
  v_contract_id uuid;
