create or replace function private.timesheet_correction_invoice_route_v1(p_timesheet_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare v_request private.timesheet_correction_requests%rowtype;
begin
  select request.* into v_request from private.timesheet_correction_requests request
    where request.state='APPLIED' and request.reversed_timesheet_id=p_timesheet_id order by request.applied_at_utc desc limit 1;
  if found then return jsonb_build_object('route','BLOCKED','blocker_code','AGENCY_INVOICE_SUPERSEDED','request_id',v_request.id); end if;
  select request.* into v_request from private.timesheet_correction_requests request
    where p_timesheet_id in(request.replacement_timesheet_id,request.reversal_timesheet_id);
  if not found then return null; end if;
  if v_request.state<>'APPLIED' then
    return jsonb_build_object('route','BLOCKED','blocker_code','CORRECTION_REQUEST_NOT_APPLIED','request_id',v_request.id);
  end if;
  if p_timesheet_id=v_request.reversal_timesheet_id then
    if v_request.original_invoice_id is null then return jsonb_build_object('route','NO_INVOICE_PLACEMENT','request_id',v_request.id); end if;
    return jsonb_build_object('route','TIMESHEET_CREDIT','request_id',v_request.id,'original_invoice_id',v_request.original_invoice_id,
      'credit_scope',jsonb_build_object('reversal_timesheet_id',v_request.reversal_timesheet_id));
  end if;
  if private.timesheet_correction_replacement_empty_v1(v_request.id) then
    return jsonb_build_object('route','NO_INVOICE_PLACEMENT','request_id',v_request.id);
  end if;
  return jsonb_build_object('route',case when v_request.return_invoice_id is not null then 'RETURN_TO_SAME_DRAFT' else 'NORMAL' end,
    'request_id',v_request.id,'return_invoice_id',v_request.return_invoice_id);
end;
$function$;

routines.body:
declare v_request private.timesheet_correction_requests%rowtype;
begin
  select request.* into v_request from private.timesheet_correction_requests request
    where request.state='APPLIED' and request.reversed_timesheet_id=p_timesheet_id order by request.applied_at_utc desc limit 1;
  if found then return jsonb_build_object('route','BLOCKED','blocker_code','AGENCY_INVOICE_SUPERSEDED','request_id',v_request.id); end if;
  select request.* into v_request from private.timesheet_correction_requests request
    where p_timesheet_id in(request.replacement_timesheet_id,request.reversal_timesheet_id);
  if not found then return null; end if;
  if v_request.state<>'APPLIED' then
    return jsonb_build_object('route','BLOCKED','blocker_code','CORRECTION_REQUEST_NOT_APPLIED','request_id',v_request.id);
  end if;
  if p_timesheet_id=v_request.reversal_timesheet_id then
    if v_request.original_invoice_id is null then return jsonb_build_object('route','NO_INVOICE_PLACEMENT','request_id',v_request.id); end if;
    return jsonb_build_object('route','TIMESHEET_CREDIT','request_id',v_request.id,'original_invoice_id',v_request.original_invoice_id,
      'credit_scope',jsonb_build_object('reversal_timesheet_id',v_request.reversal_timesheet_id));
  end if;
  if private.timesheet_correction_replacement_empty_v1(v_request.id) then
    return jsonb_build_object('route','NO_INVOICE_PLACEMENT','request_id',v_request.id);
  end if;
  return jsonb_build_object('route',case when v_request.return_invoice_id is not null then 'RETURN_TO_SAME_DRAFT' else 'NORMAL' end,
    'request_id',v_request.id,'return_invoice_id',v_request.return_invoice_id);
end;

