    'paid_minutes',0,'break_minutes',0,'hours',jsonb_build_object('day',0,'night',0,'sat',0,'sun',0,'bh',0),
    'rates',jsonb_build_object('day',0,'night',0,'sat',0,'sun',0,'bh',0),'total_pence',p_total_pence);
end;
